export const CLASSIC_BATTLE_BRIEFINGS: Readonly<Record<string, ClassicBattleBriefing>> = {
    "aiji_lameisisi": {"strategic":["公元前一二七四年，埃及新王国与赫梯帝国并立近东，反复争夺叙利亚走廊。奥龙特斯河畔重镇卡迭石扼守南北要冲，藩属阿穆鲁易帜归埃。年轻的法老拉美西斯决意北上夺回卡迭石，编成阿蒙、拉、普塔赫、塞特各路军团亲统北出；赫梯王穆瓦塔利亦倾发联军南下迎敌，两强主力直趋卡迭石。"],"tactical":["卡迭石筑于奥龙特斯河西岸台地，河水环绕其侧。拉美西斯误信细作，率阿蒙军团孤军渡河扎营，与后队拉开间距。穆瓦塔利遣战车自城东渡河冲垮拉军团，旋即围攻王营；拉美西斯乘车苦战待援，幸得海岸支队与普塔赫军团赶到夹击解围。此战两军俱疲，拉美西斯无力攻城，遂引军南还。"],"history":"公元前一二七四年五月，埃及法老拉美西斯北征叙利亚，与赫梯王穆瓦塔利于奥龙特斯河畔卡迭石会战。拉美西斯轻信诈降牧人，率阿蒙军团孤军渡河扎营，遭赫梯战车奇袭被围；幸赖海岸支队与后续军团赶到解围，次日再战未分胜负，拉美西斯引军南还，卡迭石仍属赫梯。","sources":"卡迭石铭文；埃赫银板和约"},
    "aiji_neiketaneibu": {"strategic":["公元前三七三年，埃及摆脱波斯统治独立已久，法老内克塔内布锐意整饬三角洲防务。波斯王室决意夺回富庶的尼罗河流域，命老将法那巴佐斯集结水陆大军与希腊雇佣兵沿海路南侵，直扑东门佩鲁西姆；内克塔内布亲率守军扼守门户水道迎敌。"],"tactical":["佩鲁西姆地处尼罗河东支入海口，内克塔内布预先掘壕塞道、广筑壁垒，令法那巴佐斯正面寸步难进。波斯军乘夜绕自门德斯支流登陆，却因法那巴佐斯多疑迟疑、不肯急袭孟菲斯而顿兵水网。内克塔内布乘隙增防袭扰，未几盛夏尼罗河泛滥淹没低洼波斯营寨，埃军乘水势全线反攻，法那巴佐斯败逃，埃及再保独立。"],"history":"公元前三七三年春，波斯老将法那巴佐斯会合雅典雇佣军水陆进逼埃及东门佩鲁西姆，企图收复独立的埃及。埃及法老内克塔内布预先筑垒塞道迫波斯军改由门德斯河口登陆；趁敌帅争执迟疑之际，尼罗河夏汛泛滥淹没波斯营寨，内克塔内布挥军反击大破波斯军。","sources":"西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "ailan_julushi": {"strategic":["公元前五三九年，波斯王居鲁士二世已并吞米底与吕底亚，西亚唯剩新巴比伦尚存。其时巴比伦王久居绿洲，留王子伯沙撒摄政，因冷落主神马尔杜克致朝野离心。居鲁士二世看准时机挥师渡河，于奥皮斯击破巴比伦野战军，旋即统大军南指伯沙撒留守的巴比伦城。"],"tactical":["巴比伦双垣高耸，幼发拉底河穿城而过，伯沙撒自恃城坚粮足，在城中欢庆节日疏于戒备。居鲁士二世避开强攻，命工兵在上游掘渠分流河水入泽，使穿城河道骤浅。入夜波斯精锐顺浅涸河床潜入未锁的沿河铜门，一举突入王宫，伯沙撒死于乱军；巴比伦全城归降，两河流域自此并入波斯帝国。"],"history":"公元前五三九年秋，波斯国王居鲁士二世进攻新巴比伦帝国，于奥皮斯击破巴比伦军后进逼巴比伦城。留守摄政王子伯沙撒恃坚城宴饮无备，波斯军在上游分流幼发拉底河水，趁夜沿浅涸河床潜入城内，伯沙撒败死，新巴比伦灭亡。异说：那波尼德编年史载波斯军未历大战即入城，分流河水奇袭见于希罗多德等记载。","sources":"那波尼德编年史；居鲁士圆柱；希罗多德·历史"},
    "ailan_julushi@-547": {"strategic":["公元前五四七年，波斯王居鲁士二世推翻米底后，吕底亚国王克罗伊索斯结盟东侵波斯。两军秋战难分高下，时值隆冬，克罗伊索斯断定波斯不敢冒雪深入，遂退回撒狄遣散盟军待春再战。岂料居鲁士二世看破其懈怠，率军踏雪西进直抵提姆布拉平原，逼克罗伊索斯仓促应战。"],"tactical":["提姆布拉平原辽阔平坦，克罗伊索斯尽起吕底亚长矛重骑与步兵方阵，张开两翼企图合围波斯军。居鲁士二世收拢步弓塔车结成严阵，更卸下随军骆驼辎重列于前线。吕底亚铁骑呼啸冲来，战马畏惧骆驼气味纷纷惊窜调头，阵形大乱；居鲁士二世趁势反扑击溃敌军，旋即攻克撒狄，将吕底亚并入波斯。"],"history":"公元前五四七年冬，吕底亚国王克罗伊索斯在普特里亚与居鲁士二世战平后，以为隆冬波斯必不进兵，遂回都撒狄遣散盟军待春再战。居鲁士二世冒冬疾追至撒狄城东提姆布拉平原，以辎重骆驼列前阵惊散吕底亚骑兵，合围大破克罗伊索斯主力，继克撒狄灭吕底亚。异说：年份一作前五四六年。定值：敌将取克罗伊索斯。","sources":"希罗多德·历史·第一卷；色诺芬·居鲁士的教育"},
    "ailan_julushi@-550": {"strategic":["公元前五五〇年，统治伊朗高原的米底帝国因国王阿斯提阿格斯严苛专断而贵族离心。南方附庸波斯诸部之长居鲁士二世暗结米底重臣，团结波斯各族起兵抗命。阿斯提阿格斯震怒，倾发主力御驾南征；居鲁士二世将妇孺撤入深山，率军依托帕萨尔加德隘口迎敌。"],"tactical":["帕萨尔加德群山环抱、谷口险峻，居鲁士二世凭山坡设防。阿斯提阿格斯分兵迂回两翼高山夹击，首日迫波斯军退至山巅；波斯妇孺出帐激愤将士，全军死志顿起。次日居鲁士二世率军自山顶怒吼俯冲，迎头猛撞仰攻敌阵，兼之米底怀怨贵族临阵倒戈，米底军土崩瓦解；阿斯提阿格斯被擒，波斯帝国由此崛起。"],"history":"公元前五五〇年，波斯国王居鲁士二世起兵反抗宗主米底帝国，退守波斯腹地帕萨尔加德群山。米底王阿斯提阿格斯亲率大军围攻，首日迫波斯军退保山顶；次日波斯军在妇孺激励下俯冲反扑，兼之米底贵族临阵倒戈，居鲁士二世大破米底军并生擒阿斯提阿格斯，建立波斯帝国。定值：敌将取米底王阿斯提阿格斯。","sources":"那波尼德编年史；希罗多德·历史·第一卷"},
    "ailan_shuteluke": {"strategic":["公元前一一五八年，巴比伦加喜特王朝内外交困，东方埃兰王国则在纳克昆特治下兵甲强盛。纳克昆特借累代联姻索讨巴比伦王位遭拒，遂自苏萨举兵西征；埃兰军强渡底格里斯河连克西帕尔诸城，直抵恩利尔纳丁退守的巴比伦内城之下，加喜特社稷悬于一线。"],"tactical":["巴比伦城跨幼发拉底河而筑，重垣深壕拱卫宫庙，恩利尔纳丁收拢守军闭门死守。纳克昆特先扫清外围卫城、断绝水陆粮援，再督步骑与攻城器械四面合围猛攻。孤城粮尽防溃，埃兰军破城俘获恩利尔纳丁，将汉谟拉比法典石碑与主神像拆运回苏萨，加喜特王朝自此覆灭。"],"history":"公元前一一五八年，埃兰国王纳克昆特乘巴比伦加喜特王朝衰弱大举西征，攻破巴比伦诸城，掳走汉谟拉比法典碑与纳拉姆辛胜利碑运回苏萨；加喜特末王恩利尔纳丁继续抵抗，终兵败被俘，马尔杜克神像被掳，加喜特王朝覆灭。定值：守方定为加喜特王朝，以末王恩利尔纳丁为守将代表。","sources":"苏萨埃兰王铭；巴比伦同步史"},
    "ansxi_aershake": {"strategic":["公元前二三八年前后，曾横跨西亚的塞琉古帝国正陷入空前动荡，先有埃及托勒密大军攻入叙利亚腹地，继而国王塞琉古二世又与胞弟展开惨烈王位内战，帝国在伊朗高原以东的控制力急剧崩解。","继巴克特里亚希腊总督宣布独立之后，镇守帕提亚行省的总督安德拉戈拉斯亦自行铸币脱离塞琉古王廷；然而安德拉戈拉斯既失去了帝国中枢的军事后盾，又未能赢得当地伊朗贵族与民众的拥戴。","盘踞里海东南草原的帕尼游牧部族首领阿尔沙克敏锐窥见南邻虚弱，当即统率剽悍善射的草原铁骑越过科佩特山脉南下，直指安德拉戈拉斯驻守的帕提亚重镇尼萨。"],"tactical":["尼萨坐落于科佩特山北麓绿洲走廊，北接茫茫卡拉库姆荒漠，南通伊朗高原驿道，极利骑兵高速驰骋突袭。安德拉戈拉斯麾下仅有少量希腊裔驻防步卒与仓促征集的本地兵马，既无邻省巴克特里亚驰援，又对草原游牧骑队的机动战术缺乏防备。","阿尔沙克充分发挥帕尼骑手来去如风、擅长马背返身骑射的看家本领，先以轻骑分股袭扰切断尼萨与赫卡尼亚之间的联络通道，诱使安德拉戈拉斯率军出城迎战。","平原接战之际，阿尔沙克部众以密集箭雨反复消磨守军严整队形，待其阵脚松动疲乱，再挥动披甲重骑雷霆冲阵，一举击溃总督防线，安德拉戈拉斯在败乱中被杀身亡。阿尔沙克顺利攻占尼萨与阿萨克并加冕称王，修筑要塞抵御塞琉古反扑，开创了与罗马争衡东方的安息帝国基业。"],"history":"公元前二三八年前后，趁塞琉古帝国深陷第三次叙利亚战争与兄弟内战无暇东顾，原塞琉古帕提亚总督安德拉戈拉斯率先脱离帝国自立。游牧于里海东南草原的达黑联盟帕尼部族首领阿尔沙克抓住良机，率精锐游牧骑射劲旅南下攻入帕提亚，突袭尼萨等地击败并斩杀孤立无援的安德拉戈拉斯，创建阿萨息斯王朝即中国史籍所称安息帝国。","sources":"斯特拉波·地理志·第十一卷；查士丁·腓力史概要·第四十一卷"},
    "aqimeinide_daliushi": {"strategic":["公元前五二一年，波斯宫廷剧变未久，大流士一世诛除夺位者登基，帝国各省趁乱纷叛。巴比伦贵族尼丁图-贝尔冒称故王之子自立为王，两河诸城景从。大流士一世深知巴比伦乃帝国赋税命脉，不容坐视复国，遂亲统波斯与米底劲旅火速西征，直扑尼丁图-贝尔据守的巴比伦。"],"tactical":["巴比伦外有两河环护，内有重垣可恃。尼丁图-贝尔遣舟师封锁底格里斯河渡口；大流士一世命士卒乘皮筏战马强渡破防，复败敌主力于幼发拉底河畔，迫其退入城中死守。大流士一世乘胜合围巴比伦，分道猛攻突破城防，生擒处死尼丁图-贝尔，稳住两河大局并进而荡平各省叛乱。"],"history":"波斯王冈比西斯二世死后帝国大乱，大流士一世夺位之际各省纷叛，巴比伦贵族尼丁图-贝尔冒称前王之子自立为巴比伦王。大流士一世亲统大军强渡底格里斯河，再败敌于幼发拉底河畔，合围攻破巴比伦城并擒杀尼丁图-贝尔。异说与定值：贝希斯敦铭文载其败亡于前五二二年末，定稿表取前五二一年破城。","sources":"贝希斯敦铭文；希罗多德·历史·第三卷"},
    "bfe2_esarhaddon": {"strategic":["公元前六七一年，距首次征埃受挫已过两载，推罗王再度倚仗法老塔哈尔卡撑腰背叛亚述。亚述王以撒哈顿痛定思痛，预先征调阿拉伯驼队运水，分兵钳制推罗，亲统大军稳步越过西奈荒漠。亚述军入埃及东境后连破拦截兵马，沿三角洲边缘推进，直抵下埃及都城孟菲斯。"],"tactical":["孟菲斯扼守尼罗河三角洲顶点，白墙高耸、水陆辐辏，塔哈尔卡亲督守军背城迎战。以撒哈顿先于城外野战击溃埃军并射伤塔哈尔卡，随即水陆合围孟菲斯；亚述军在箭雨掩护下架冲车云梯猛攻，半日便突破外郭杀入内城。塔哈尔卡弃城南逃底比斯，以撒哈顿俘其王室家眷，将下埃及纳入亚述版图。"],"history":"公元前六七一年夏，亚述王以撒哈顿吸取前败教训，征调阿拉伯驼队供水穿越西奈，连破埃及边防直抵下埃及都城孟菲斯。法老塔哈尔卡力战负伤南逃底比斯，以撒哈顿攻克孟菲斯，俘获王后太子，册封三角洲诸侯，将下埃及纳入亚述版图。","sources":"以撒哈顿辛吉尔利胜利碑；巴比伦编年史"},
    "bfe2_esarhaddon@-673": {"strategic":["公元前六七三年，亚述王以撒哈顿虽已震慑叙利亚诸邦，埃及法老塔哈尔卡却屡向腓尼基输送财货援兵，煽动沿海诸城反叛。以撒哈顿踏平西顿后决意直捣祸根，集结远征军自迦南南境强穿西奈荒漠，企图抢先夺下埃及东境门户佩鲁西姆，打开尼罗河三角洲。"],"tactical":["佩鲁西姆横亘西奈沙碛尽头与尼罗河东支水网之间，遍布盐泽流沙。以撒哈顿督军缺水急行，抵阵时已人困马乏、队列拉长。塔哈尔卡早已凭河渠壁垒严阵以待，趁亚述战车步卒陷于沙泽泥泞之际全线猛攻。亚述军久行力竭伤亡惨重，以撒哈顿果断收拢残师北撤返国，留待日后再图埃及。"],"history":"公元前六七三年初春，亚述王以撒哈顿为铲除黎凡特叛乱的幕后支柱埃及，率军强行穿越西奈荒漠，进攻埃及东境门户佩鲁西姆。因行军过急、缺水疲敝，亚述军遭埃及法老塔哈尔卡迎头痛击而大败，以撒哈顿撤军返国。异说：巴比伦编年史或折算为前六七四年，定稿表取前六七三年。","sources":"巴比伦编年史；亚述年代记"},
    "bfe2_pang_juan": {"strategic":["公元前三四二年，魏国国力复振，大将庞涓辅太子申倾国攻韩，欲重夺中原霸权。韩国危急求救于齐，齐国复遣主帅田忌越境直扑魏都大梁；正督军攻韩的庞涓惊闻后方告急，新仇旧恨交织，当即撤韩围东向，追击田忌主力直奔马陵道。"],"tactical":["马陵道夹于崇山幽谷之间，林密路窄，极易设伏。庞涓入边境见田忌东退，查齐营遗灶逐日锐减，喜认齐卒怯懦逃亡，遂撇下步卒辎重，亲率精锐轻骑昼夜急追，日暮扎入马陵道。夜色中庞涓见道旁刮皮大树写有墨字，命点火辨认；火亮处两侧山崖强弩齐发，狭道魏军死伤枕藉，庞涓拔剑自刎，魏霸就此终结。"],"history":"公元前三四二年，魏大将庞涓与太子申率军伐韩，齐威王以田忌为将、孙膑为师直趋大梁救韩，迫庞涓撤围回救。齐军逐日减灶示弱，庞涓弃步卒率轻骑兼程追入马陵道，夜间举火读树中伏，齐弩齐发，魏军大溃，庞涓自刎。定值：同场三行统一取前三四二年、战场马陵道。","sources":"史记·孙子吴起列传；史记·魏世家；战国策"},
    "bfe2_pang_juan@-353": {"strategic":["公元前三五三年，魏国大将庞涓统精锐魏武卒猛攻赵都邯郸逾年，刚拔外城之际，后方魏都大梁忽传火急警报。原来齐国应赵求援，命大将田忌趁魏国内空虚挥师西进，扬言直捣大梁；庞涓不敢坐视根本有失，只得率久战主力掉头南下，疾趋桂陵迎堵田忌。"],"tactical":["桂陵地处黄河南岸通往大梁的孔道，丘陵沟渠交错。庞涓自恃魏武卒悍勇，急于解大梁之危，催督疲师丢弃粮车昼夜狂奔，致队列拉长脱节。岂料田忌早已抢占桂陵险要筑垒设伏、蓄锐待敌；庞涓前锋撞入伏击圈，遭齐军四面合击拦腰截断，全军溃散，庞涓亦在混战中被俘，魏国霸气大挫。"],"history":"公元前三五四年魏将庞涓围攻赵都邯郸，次年即前三五三年攻克邯郸之际，齐将田忌与军师孙膑率师直扑魏都大梁。庞涓闻警，率久战疲师弃辎重星夜回救，在桂陵中齐军以逸待劳之伏而大败被俘，后获释归魏。定值：同场三行年份统一取前三五三年。","sources":"史记·孙子吴起列传；史记·魏世家；战国策"},
    "bfe3_13": {"strategic":["公元前二二五年，秦国相继吞灭韩、赵、魏三国并攻破燕都蓟城，东方大地唯有广土众民的楚国尚能与强秦正面对决。秦王嬴政急欲一鼓作气荡平南方，拒绝老帅王翦倾全国重兵稳扎稳打之议，派风头正劲的少壮猛将李信与蒙恬分兵两路大举侵楚。","秦军初入淮颍一带势如破竹，连陷平舆、寝丘等重镇，楚王负刍急命世家名将项燕总揽全国兵马迎敌。","面对锋芒毕露、长驱深入的李信大军，老谋深算的项燕并未在正面城池与之硬拼消耗，而是暗中集结楚国精锐主力悄然转移机动，静候骄狂冒进的李信露出致命破绽，尾随秦师一路逼向淮北要冲城父。"],"tactical":["城父位于颍水与涡水之间的淮北平原，乃是李信与蒙恬两路秦军约定的会师枢纽。此时李信刚刚攻克楚西鄢郢故地，自以为楚人一触即溃、灭楚大功唾手可得，遂督促麾下秦卒日夜急行东返城父争功，沿途战线拉得极长，士卒人困马乏、疏于筑垒戒备。","项燕瞅准战机，亲率养精蓄锐的楚国主力紧紧咬在李信大军尾后，全军将士连续三日三夜不解衣甲、疾趋猛追，始终保持随时扑击之势。待李信所部行抵城父外围、尚未与蒙恬合兵且立营未稳之际，项燕一声令下，压抑已久的楚军将士怀着保家卫国的血勇从四面八方雷霆杀出。","疲惫骄怠的秦军猝不及防，接连两座大营被楚师踏破，麾下七名都尉悉数战死，李信仅率残兵狼狈西逃；项燕此役创下秦王嬴政横扫六国以来最惨痛的一场败绩，令楚国国祚再延寒暑。"],"history":"公元前二二五年，秦王嬴政已灭韩、赵、魏，决意南下灭楚，轻信少壮将领李信豪言，命李信与蒙恬分道伐楚。秦军初战连克平舆、寝丘，李信复破鄢郢后引军东向拟与蒙恬会师城父。楚国大将军项燕洞悉秦军远深入境、骄兵轻进之弊，率楚军主力收敛锋芒尾随紧追三日三夜不息，趁李信军疲垒虚之际在城父突然发起雷霆猛攻，连破秦军两座大营、斩杀七都尉，重创李信。","sources":"史记·白起王翦列传；史记·楚世家"},
    "bfe3_13@-224": {"strategic":["公元前二二四年，城父大捷的喜悦尚未散尽，楚国便迎来了秦国倾尽国力的灭国反扑。秦王嬴政亲自向老将王翦认错，将秦国全部机动重兵悉数交予王翦统领南征。楚王负刍紧急动员江淮全境男丁，再度托付威望卓著的大将军项燕奔赴淮北前线迎击。","然而这一次项燕面对的不再是骄狂急躁的李信，而是深沉如渊的宿敌王翦；秦军踏入楚境后当即在平舆一带扎下连绵大营，高垒深沟闭门不出。项燕欲重施野战诱击故智，屡次派兵赴秦营门前挑战辱骂，王翦却稳如磐石按兵不动，两支举国大军在淮北旷野硬生生对峙了一整年。"],"tactical":["蕲县蕲南地处淮北睢水与涡水流域，原野平阔，道路四通。项燕率领临时征集的各路楚军在野地苦耗经年，见王翦大营终日安静、秦卒在营内投石跳跃戏耍而绝不出战；项燕误判秦军师老意怠不敢决战，加之楚军粮饷难继，遂下令全军拔营向东移防休整。","殊不知王翦苦等一年正是为了这一刻，营中养精蓄锐、力气无处发泄的秦国虎贲一听开拔追敌，人人如猛虎出柙般狂扑而出。趁楚军行列拉长、首尾正在行进转换而未及回身结阵之际，王翦率秦军主力从背后排山倒海掩杀而至，在蕲县蕲南将楚国大军冲得七零八落。","项燕披发挥剑力战难挽狂澜，眼见江东子弟与楚国精锐尽数覆没，在绝望悲愤之中拔剑自刎殉国；随着这位擎天老帅陨落，次年寿春陷落，累代荆楚宗社终归烟灭。"],"history":"公元前二二四年，秦王嬴政接受李信惨败教训，亲请老帅王翦统倾国大军再伐楚国，楚大将军项燕亦征发全境兵马于平舆、陈南相拒。王翦吸取前车之鉴筑垒坚守逾年不战，每日优厚休养士卒至投石超距思战；项燕见久耗无果引军东移，王翦乘楚军拔营移动之际全军追击，在蕲县蕲南大破楚军，项燕兵败自杀，楚国主力覆亡。","sources":"史记·白起王翦列传；史记·楚世家"},
    "bfe3_9": {"strategic":["公元前二六二年，秦国攻克韩国重镇野王，拦腰斩断上党郡与韩都新郑的联系；上党郡守冯亭不愿降秦，献计举全郡城邑转投赵国，赵孝成王贪恋上党膏腴之地欣然受纳。","秦廷苦战得地却被赵国凭空截胡，秦昭襄王勃然震怒，命骁勇善战的宿将王龁统率秦军主力东进夺取上党，上党军民纷纷北奔长平投靠赵师。赵孝成王急遣宿将廉颇率重兵进驻长平接应设防，王龁挥动锐气正盛的秦国虎狼之师紧追不舍，跨入太行腹地直逼廉颇防线，拉开长平大战的铁血序幕。"],"tactical":["长平群山环峙，丹水自北向南穿谷而流，廉颇初抵战场时沿空仓岭至丹水西岸分筑多道前哨壁垒层层阻截。王龁率秦军精锐迎头猛扑，在山地争夺战中展现出凌厉攻势，先于初夏攻破赵军前锋防线斩杀赵军都尉，盛夏再拔西岸四处要塞、击斩赵裨将茄，打得赵军野战连连失利。","廉颇见秦锋极锐难与争锋，果断收拢主力退往丹水东岸，依山凭水修筑起绵延险固的绵延石长城，任凭王龁如何遣兵挑战辱骂，始终闭营深守绝不出战。两军隔丹水僵持旷日持久，王龁虽牢牢掌控西岸主动权却难破坚壁；","直至秦相范雎巧施反间计诱使赵王以赵括换下廉颇，秦王密遣白起赴营挂帅、王龁改任副帅全力配合，诱敌深入后截断粮道合围赵括大军，终助秦国铸就震古烁今的长平全胜。"],"history":"公元前二六二年秦拔韩野王，上党献赵。公元前二六〇年前期，秦昭襄王命左庶长王龁率军攻占上党，继而进逼长平迎战赵孝成王派出的老将廉颇。王龁连续攻破赵军前哨壁垒、斩杀赵裨将茄与都尉，迫使廉颇退守丹水东岸筑长垒坚守不出；相持日久后秦施反间计诱赵括代廉颇，秦廷密派白起为上将军、王龁改任副将，协同合围歼灭赵军主力。","sources":"史记·白起王翦列传；史记·秦本纪"},
    "bfe3_9@-257": {"strategic":["公元前二五八年，秦昭襄王急欲趁长平大胜之威一举吞灭赵国，先行派王陵率军围攻赵都邯郸却折损重兵难下，武安君白起直言赵国上下同仇敌忾、诸侯必救，坚辞挂帅。秦王遂改命长平宿将王龁接掌前线帅印，增调重兵继续合围邯郸。","王龁督军连月猛扑，将邯郸困成一座绝粮孤城，秦廷更放话威慑魏楚诸侯不得妄动。不料至公元前二五七年冬，原本屯驻邺城观望的魏军突发剧变，信陵君魏无忌盗符杀将夺取精兵，联合南路北上的楚国大军星夜兼程杀奔邯郸，王龁不得不分转兵锋在邯郸城外迎战来势汹汹的合纵援师。"],"tactical":["邯郸城垣坚厚，城外秦军连营环绕，然秦师自长平以来连年暴露于外，攻城死伤惨重，将士早已师老兵疲。面对魏无忌亲率精选魏武卒自西面发起的猛烈突击，王龁急忙调集主力迎堵；","怎奈魏军人人死战，楚国援军亦自侧翼压上，邯郸城门更骤然洞开，平原君率城中敢死之士从背后杀入秦军围城阵线。三面夹击之下，久顿坚城之下的秦军防线终于支撑不住，营垒接连被魏赵联军冲破，阵形大乱。","王龁眼见大势已去，为免主力全军覆没于河北，果断收拢本部残军且战且退，解开邯郸重围西撤渡河退保汾城，仅留偏将郑安平部被联军团团围困后降赵；秦国一举灭赵的企图虽暂告受挫，王龁仍保全骨干归秦，日后继续统兵为秦东征。"],"history":"公元前二五八年秦将王陵攻赵都邯郸失利，白起称病不出，秦昭襄王遂命长平功臣王龁接替王陵统率秦军主力继续猛攻邯郸。王龁围困邯郸经年，赵都粮绝垂危；公元前二五七年冬，魏信陵君魏无忌窃符夺晋鄙军北上，会合楚春申君援军猛袭秦营，城内平原君死士开门夹击，久师疲敝的王龁大败解围，撤往汾城。","sources":"史记·白起王翦列传；史记·魏公子列传"},
    "bfe_antigonus": {"strategic":["公元前四世纪末，亚历山大麾下诸继业者历经二十余年混战已各自称王，其中坐拥小亚细亚、叙利亚与爱琴海霸权的安提柯一世势力最为庞大，年届八旬仍壮心不已，意图吞并马其顿本土，重现亚历山大帝国一统江山。","这股咄咄逼人的势头迫使马其顿王卡山德、色雷斯王利西马科斯、埃及王托勒密与东方霸主塞琉古再度捐弃前嫌，结成生死同盟共抗安提柯。利西马科斯率先跨海侵入小亚细亚牵制，塞琉古更与印度孔雀王朝议和，带着换来的庞大战象群翻越高原西进会师。","安提柯一世急召正在希腊作战的爱子德米特里率军渡海归援，父子合集重兵迎向弗里吉亚腹地的伊普苏斯平原，整座希腊化世界的命运系于此役。"],"tactical":["伊普苏斯平原地势辽阔平缓，极利大军团方阵与战象骑队展开决战。安提柯一世亲自统率久历沙场的重装长矛方阵坐镇中军，将仅有的少量战象摆在阵前，命爱子德米特里统领最精锐的重骑队居右翼主攻。","两军交锋后，前排战象与方阵激烈碰撞，右翼德米特里骁勇无匹，一鼓作气冲垮塞琉古之子安条克统领的联军左翼骑兵；不料德米特里贪功穷追溃敌，竟一路追出战场过远而收拢不及。","敏锐的塞琉古看准安提柯中军右侧门户大开，立即驱使从印度带回的浩大象群横插而入，筑起一道战马根本不敢靠近的活体高墙，彻底堵死了德米特里回救乃父的通道。紧接着联军弓骑队绕着失去侧翼掩护的安提柯方阵盘旋攒射，迫使部分士卒倒戈溃散；","白发苍苍的安提柯一世至死翘首期盼儿子杀回救驾，终被密集标枪攒刺倒毙阵中，统一帝国的最后旧梦随他一同落幕。"],"history":"公元前三〇一年，年逾八旬的继业者霸主独眼安提柯一世与其子德米特里一世在弗里吉亚的伊普苏斯平原，迎战塞琉古、利西马科斯与卡山德援军组成的反安提柯同盟。德米特里率精锐骑兵击溃联军骑翼但追击过远，被塞琉古从印度换回的大批战象排成屏障截断归路；联军轻骑环射安提柯中军方阵，安提柯一世苦盼爱子回援不至，身中乱枪阵亡，帝国被瓜分。","sources":"普鲁塔克·德米特里传；西西里的狄奥多罗斯·历史丛书·第二十卷"},
    "bfe_antigonus@-316": {"strategic":["公元前三一六年隆冬，帕莱塔西奈血战未分胜负之后，欧墨涅斯率王室联军进入伊朗腹地富庶的加比埃奈绿洲分散扎营过冬。驻扎米底的安提柯一世探知敌营彼此相隔数日路程，决意行险一搏，率精兵在滴水成冰的寒冬强行穿越荒无人烟的盐碱大漠，企图趁敌军未及聚拢予以各个击破。","不料沙漠寒夜中士卒生火取暖暴露行踪，机敏的欧墨涅斯在山顶遍燃空营篝火吓止敌军前锋；他趁隙将四散各部与战象悉数集结完毕，两大宿敌遂在加比埃奈盐碱平原迎来决定生死的最后一战。"],"tactical":["加比埃奈原野寸草不生，地表铺满厚厚一层松软干燥的白色盐碱细沙。两军战象与铁骑甫一交锋奔腾，滚滚盐尘便拔地而起，将整片天空遮蔽得伸手不见五指。中路战场上，欧墨涅斯麾下无敌的银盾老兵再度发威，如砍瓜切菜般杀穿安提柯长矛步阵；","右翼安提柯一世与爱子德米特里则率优势重骑冲破敌方左翼，迫使东方骑兵统帅弃阵远遁。","激战正酣之际，安提柯一世在漫天白雾中突发奇想，见欧墨涅斯后方大营距前线不远且守备空虚，当即密令轻骑借盐尘掩护悄悄绕过主战场，不费吹灰之力将银盾老兵随军携带数十年的金银战利品与妻儿老小尽数掳获。","战罢银盾兵虽在阵前获胜，听闻毕生家当与眷属落入敌手顿时方寸大乱，竟暗中派人向安提柯一世乞还家产，亲手将统帅欧墨涅斯五花大绑献入安提柯帐下处死，安提柯一世自此雄霸整个亚洲。"],"history":"公元前三一六年冬，安提柯一世冒严寒强穿荒漠突袭分散过冬的欧墨涅斯各部未果，两军在伊朗中部加比埃奈干涸盐碱荒原展开终极决战。开战后蹄踏盐土扬起遮天白尘，安提柯一世灵机一动，借浓尘掩护密派米底与塔兰托骑兵绕过正面战场，一举端掉欧墨涅斯毫无防备的后方大营；虽银盾兵再度正面击溃安提柯步阵，但为赎回毕生积蓄与妻儿，银盾兵哗变捆献欧墨涅斯投降，安提柯独霸亚洲。","sources":"普鲁塔克·欧迈尼斯传；西西里的狄奥多罗斯·历史丛书·第十九卷"},
    "bfe_antigonus@-317": {"strategic":["公元前三一七年，亚历山大帝国分裂混战愈演愈烈，手握小亚细亚重兵的独眼宿将安提柯一世决心铲除王室派在亚洲最后的擎天柱欧墨涅斯。这位出身希腊文书的奇才欧墨涅斯不仅收服了亚历山大留下的传奇老兵银盾军团，更东进伊朗高原赢得东方各上行省总督携大批战象与骑兵倾力归附。","安提柯一世一路紧追跨越两河进入酷热山地，历经河岸挫折后休整补充，于深秋在伊斯法罕附近的帕莱塔西奈山谷与欧墨涅斯大军狭路相逢，两支完全继承马其顿军事衣钵的庞大军团隔着溪涧摆开了堂堂之阵。"],"tactical":["帕莱塔西奈战场背山临谷，双方皆以长矛方阵居中、战象掩护阵前、铁骑分张两翼。交锋伊始，安提柯一世左翼轻骑统帅不听号令擅自前出挑战，遭欧墨涅斯调动战象与优势骑兵迎头痛击而溃败；","中路战况更为凶险，欧墨涅斯麾下虽已年逾花甲却战无不胜的银盾老兵以排山倒海之势撞碎安提柯长矛步阵，杀得安提柯中军尸横遍野节节败退。","全军濒临崩盘的危急关头，部将纷纷劝安提柯一世退保高地，独眼老帅却冷静窥见银盾兵因猛追过速而与欧墨涅斯左翼骑兵之间脱开一道巨大豁口，当即亲率右翼伙伴重骑悍然扎进缺口，从侧背猛冲敌翼。这一记神来之笔迫使欧墨涅斯紧急召回正在追杀的部队回救，入夜双方精疲力竭各自收兵；","安提柯一世凭借过人意志连夜催动大军重返战场抢占遗尸阵地安营，硬生生在败局边缘夺回了战略主动。"],"history":"公元前三一七年秋，第二次继业者战争期间，亚洲统帅安提柯一世追击效忠马其顿阿吉亚德王室的希腊名将卡迪亚的欧墨涅斯进入伊朗高原帕莱塔西奈山地。两军展开继业者时代规模浩大的正面会战，欧墨涅斯麾下老迈却无敌的银盾兵击溃安提柯方阵，左翼亦占优；危急关头安提柯一世亲率右翼重骑大胆斜插敌阵裂口反击得手，入夜重整返战夺占战场，迫欧墨涅斯撤离。","sources":"西西里的狄奥多罗斯·历史丛书·第十九卷；普鲁塔克·欧迈尼斯传"},
    "dibisi_tahaerka": {"strategic":["公元前六七三年，新亚述帝国囊括两河与黎凡特大部，唯尼罗河流域在法老塔哈尔卡治下统一强盛，堪与亚述抗衡。塔哈尔卡持续资助沿海诸城抗亚述，引来亚述王以撒哈顿倾师南侵。闻知敌军强穿西奈沙碛直扑东门佩鲁西姆，塔哈尔卡即调埃及与库施精锐北上东境迎击。"],"tactical":["佩鲁西姆地处西奈沙漠与尼罗河三角洲水网交界要冲，沙丘与河汊交错。塔哈尔卡依托水道塞堡严密布防、蓄锐待敌；以撒哈顿催军昼夜穿过缺水荒原，抵前线时饥渴交迫、阵形散乱。待亚述前锋踏入湿软沙泽受阻，塔哈尔卡挥师全线反扑重创敌军，迫使以撒哈顿北撤，成功保住埃及独立。"],"history":"公元前六七三年初春，亚述王以撒哈顿率军疾穿西奈走廊远征埃及东门佩鲁西姆。埃及第二十五王朝法老塔哈尔卡预作整备，乘亚述军长途跋涉疲敝之际迎头痛击，大败亚述远征军，迫使以撒哈顿退回亚述。异说：巴比伦编年史或折算为前六七四年，定稿表取前六七三年。","sources":"巴比伦编年史；以撒哈顿王家铭文"},
    "dibisi_tahaerka@-671": {"strategic":["公元前六七一年，埃及法老塔哈尔卡击退亚述首次入侵两载后，继续联结推罗共抗亚述。亚述王以撒哈顿卷土重来，重金征募阿拉伯驼队克服西奈缺水天险，突破埃及东门防线疾进。塔哈尔卡急调上下埃及与库施精锐会聚古都孟菲斯，决意凭尼罗河枢纽坚城阻挡亚述兵锋。"],"tactical":["孟菲斯控扼上下埃及咽喉，白墙外环绕尼罗河干流与深壕。塔哈尔卡披挂坐镇，先遣精兵出城挫敌锐气；怎奈亚述铁甲步骑层层压进，塔哈尔卡督战中箭负伤，守军退回城内固守。以撒哈顿旋即水陆合围，督冲车云梯强攻撕裂外城；塔哈尔卡见孤城难支，突围南撤底比斯，留存南方复国火种。"],"history":"公元前六七一年夏，亚述王以撒哈顿借阿拉伯驼队供水越过西奈，突破埃及东防进逼孟菲斯。法老塔哈尔卡亲督守军在孟菲斯浴血拒战，终因身受箭伤、外郭被破而南退上埃及底比斯，孟菲斯陷落，王室家眷被俘，塔哈尔卡其后仍据南方继续抗争。","sources":"巴比伦编年史；以撒哈顿辛吉尔利胜利碑"},
    "dongxian_sunbin": {"strategic":["公元前三四二年，魏将庞涓大举伐韩，韩国急向齐廷乞师。齐军师孙膑献缓救待敝之策，待韩魏相持俱疲后，辅主将径逼魏都大梁以攻其必救。前线庞涓果然盛怒撤围东返追截，孙膑遂因势利导，引诱宿敌一步步踏向预设绝地马陵道。"],"tactical":["马陵道深涧绝壁夹束羊肠狭路。孙膑洞悉三晋兵悍而轻齐，命齐军佯退并逐日减灶，伪造士卒逃散假象。庞涓查灶大喜，果弃大军仅携轻骑穷追；孙膑算定其日暮必抵马陵道，预伐木塞路，刮白大树书字，伏善射弩手令见火即发。庞涓夜入绝谷举火读字，刹那乱箭攒射，魏军覆没、庞涓自戕，孙膑大仇得报。"],"history":"公元前三四二年，魏帅庞涓攻韩，齐威王命田忌为将、孙膑为师趋大梁诱庞涓回师。孙膑利用庞涓悍勇轻齐之心，命齐军逐日减灶诱其孤军夜追，算定行程于马陵道刮树书字、伏强弩待火齐射，歼灭魏军精锐逼死庞涓。定值：同场三行统一取前三四二年、战场马陵道。","sources":"史记·孙子吴起列传；孙膑兵法"},
    "dongxian_sunbin@-353": {"strategic":["公元前三五三年，魏将庞涓重兵围困赵都邯郸，赵急乞师于齐。齐王用曾遭庞涓陷害受膑刑的孙膑为军师，坐帷车辅主将出征。孙膑力劝勿赴河北硬拼，主张乘魏境空虚直趋大梁以攻其必救；齐军依计西进，果诱庞涓弃赵回援，奔向孙膑预设的桂陵战场。"],"tactical":["桂陵控扼魏师南返大梁的咽喉，冈阜隐蔽。孙膑先遣偏师佯攻平陵示弱以骄庞涓之心，使其毫无戒备督疲师兼程南奔；同时指挥齐军主力进驻桂陵高坡构筑伏阵，饱餐蓄锐。待庞涓率饥疲散乱的魏军闯入谷口，孙膑挥旗令正面截堵、两翼包抄；魏武卒力竭阵乱土崩瓦解，庞涓当场被擒，围魏救赵名扬天下。"],"history":"公元前三五三年，魏帅庞涓攻赵都邯郸，齐威王命田忌为将、曾受膑刑的孙膑为军师发兵救赵。孙膑劝阻赴赵硬拼，定围魏救赵之策直趋大梁，诱庞涓急行回救，并于桂陵设伏大破魏军、生擒庞涓。定值：同场三行年份统一取前三五三年。","sources":"史记·孙子吴起列传；孙膑兵法·擒庞涓"},
    "gen_alexander_great": {"strategic":["公元前三三四年，马其顿王亚历山大稳固希腊后方后，统精锐渡赫勒斯滂海峡东征波斯。效力波斯的希腊名将门农力劝诸总督焚粮清野，波斯总督们却拒不采纳；敌军集铁骑与门农麾下雇佣步卒扼守格拉尼库斯河，亚历山大闻讯即挥师迎击。"],"tactical":["格拉尼库斯河水急岸陡，波斯诸总督将骑队紧贴东岸排开，反把门农的雇佣步阵留于后坡。亚历山大拒纳待明晨偷渡之议，先遣前锋诱敌，随即亲率伙伴骑队斜涉急流强冲敌阵。陡岸肉搏中亚历山大头盔被劈仍力战破敌，马其顿方阵亦登岸压垮敌骑，继而合围全歼后坡雇佣军；门农仅以身免，小亚细亚门户洞开。"],"history":"公元前三三四年五月，马其顿国王亚历山大渡赫勒斯滂海峡东征波斯。希腊客将门农向波斯诸总督献坚壁清野之策遭拒，波斯军沿格拉尼库斯河陡峭东岸列骑兵于前、雇佣步兵于后。亚历山大不待次日，午后亲率伙伴骑兵斜渡急流肉搏破阵，全歼波斯雇佣军，敞开小亚细亚大门。","sources":"阿里安·亚历山大远征记·第一卷；普鲁塔克·亚历山大传"},
    "gen_alexander_great@-331": {"strategic":["公元前三三一年，亚历山大历经漫长围攻拔除腓尼基海岛坚城推罗并收服埃及，断绝波斯海上威胁后再度挥师东指两河腹地。波斯国王大流士三世求和遭拒后，征调巴克特里亚、塞种、印度与两河各省精锐重骑、战象及新造卷刃镰刀战车；","他吸取伊苏斯地形狭窄的教训，特选底格里斯河以东辽阔的高加米拉原野安营，令人将旷野土丘杂草尽数铲平。","亚历山大顺利渡过两河抵近战场，面对漫山遍野的波斯营火，断然否决部将趁夜偷袭的建议，坦然宣言绝不偷取胜利，令全军安然酣睡，待天明在阳光之下与大流士三世堂堂正正决出亚洲之主。"],"tactical":["高加米拉旷野一望无际，大流士三世战线两翼远远超出马其顿军阵，防不胜防。亚历山大匠心独运摆出空心双线阵，在主力方阵背后另设一排可随时转身向外迎敌的二线步卒以防四面合围，命帕曼纽死守左翼，自己亲统伙伴骑队与机动轻步卒居右翼不断向右斜行机动。","大流士三世唯恐亚历山大引军脱离铲平的战车场地，急令波斯左翼巴克特里亚重骑上前拦截，同时放出大批镰刀战车猛冲马其顿中阵；马其顿标枪手先射杀御者，方阵士卒冷静让开通道放空战车再从容合围歼之。","与此同时波斯左翼因急于跟随亚历山大右移，与大流士三世中军之间骤然拉出一道空隙；亚历山大眼疾手快，当即将伙伴骑队与跟进方阵收聚成锋利无比的巨型楔形阵，掉头直刺缺口杀奔大流士三世车前。","短兵相接间大流士三世再度丧胆策马北逃，此时左翼帕曼纽正被波斯右翼围攻告急，亚历山大立即勒马回救击退强敌，高加米拉全胜宣告波斯帝国大势彻底终结。"],"history":"公元前三三一年十月一日，攻克推罗与埃及的亚历山大东渡幼发拉底河与底格里斯河，与波斯王大流士三世在阿尔贝拉西北的高加米拉大平原展开决定帝国存亡的总决战。大流士三世预先铲平地面以利镰刀战车与优势骑兵包抄；亚历山大拒绝夜袭，布下双层空心方阵保护侧后，右翼斜向机动拉扯波斯防线露出缺口，随即摆成楔形阵直插大流士三世本阵再度迫其败逃，终结波斯帝国主力。","sources":"阿里安·亚历山大远征记·第三卷；库尔提乌斯·亚历山大大帝史"},
    "gen_alexander_great@-333": {"strategic":["公元前三三三年秋，亚历山大横扫小亚细亚并穿过奇里乞亚门险隘南进，波斯大王大流士三世终于在巴比伦集结起倾国大军御驾亲征。起初大流士三世驻营叙利亚开阔平原候战，因亚历山大患病耽搁，大流士三世误以为马其顿王畏怯不敢出山；","他竟贸然弃广就狭，率大军翻越阿马努斯山北口插到马其顿军后背，夺占伊苏斯截断了亚历山大的陆上归路。亚历山大闻报非但不惊，反而欣喜若狂，深知波斯大军自投狭窄海岸正是上天赐予的决胜之地，当即令全军掉头星夜北返，穿过沿海山门直扑大流士三世设防的伊苏斯皮纳罗斯河畔。"],"tactical":["伊苏斯战场西临海湾、东靠陡峭阿马努斯山麓，皮纳罗斯河横穿狭小沿海走廊，大流士三世被迫将浩荡兵马层层叠叠挤在河北岸，前岸更打下木桩构筑胸墙，以希腊雇佣精兵居中、重骑临海居右。亚历山大将防海侧的左翼重任交给老帅帕曼纽，自领伙伴骑队与持盾卫队部署在靠山的右翼。","开战后马其顿中路方阵在攀爬陡峭河岸时一度脱节，遭波斯雇佣军猛击陷入苦战；亚历山大见状毫不迟疑，亲率右翼铁骑疾风般涉水冲垮波斯左翼山地防线，旋即调转矛头沿河岸向内斜插，迎着刀光箭雨径直杀向大流士三世高耸的御用战车。","亚历山大大腿被刺伤仍死战不退，御车周边波斯显贵纷纷倒毙，大流士三世胆寒之下弃车换马仓皇逃离战场。亚历山大克制追王冲动，及时回师解救苦撑的方阵与左翼，波斯全军随之大溃，大流士三世的母后、王后与子女尽数被俘，腓尼基与叙利亚门户自此敞开。"],"history":"公元前三三三年十一月，波斯国王大流士三世亲统大军自叙利亚翻越阿马努斯山隘，绕到南下马其顿军背后截断其交通线，屯兵奇里乞亚海湾与群山之间的伊苏斯狭长平原皮纳罗斯河北岸。亚历山大掉头北返迎战，借助狭小地形抵消波斯人数优势，亲率右翼伙伴骑兵涉河击破波斯左翼后直扑大流士三世高大战车，吓退大流士三世并回救左翼，夺获波斯王室家眷，彻底扭转东征战略主动权。","sources":"阿里安·亚历山大远征记·第二卷；普鲁塔克·亚历山大传"},
    "gen_aristides": {"strategic":["公元前四七九年，波斯陆军主力仍留驻希腊，统帅马尔多尼乌斯遣使诱雅典单独媾和以瓦解同盟。雅典将军阿里斯提德严词拒降，敦促斯巴达发兵会师；马尔多尼乌斯遂退入易骑的彼奥提亚平原。阿里斯提德率雅典重步兵会合诸邦联军翻山追击，对峙于普拉提亚。"],"tactical":["普拉提亚南依山麓、北临河原，马尔多尼乌斯据河北筑木寨，纵骑截粮毁泉迫联军夜移营地。天明联军队列脱节，马尔多尼乌斯误认敌军溃逃，挥师渡河猛扑斯巴达军；左翼阿里斯提德驰援途中遭亲波斯的底比斯方阵缠住。激战中斯巴达军阵斩马尔多尼乌斯，阿里斯提德亦击溃底比斯劲旅，合兵攻破波斯木寨。"],"history":"公元前四七九年八月，留驻希腊的波斯统帅马尔多尼乌斯再占雅典后退至普拉提亚寻战，阿里斯提德统雅典重装步兵居希腊联军左翼。波斯骑兵断水截粮迫联军夜撤，马尔多尼乌斯误认联军溃逃渡河猛扑，被斯巴达军击毙；阿里斯提德亦击溃亲波斯的底比斯军，会师攻破波斯木寨，终结波斯侵希。","sources":"希罗多德·历史·第九卷；普鲁塔克·阿里斯提德传"},
    "gen_artaphernes": {"strategic":["公元前四九八年，波斯治下的爱奥尼亚诸邦掀起叛乱。米利都僭主阿里斯塔哥拉斯惧遭吕底亚总督阿尔塔弗涅斯治罪，煽动各城反波斯并引雅典战舰助战。联军自以弗所登陆翻山，出其不意直扑阿尔塔弗涅斯驻守的首府撒狄，企图瘫痪波斯西疆中枢。"],"tactical":["撒狄下城铺展河谷，背靠三面绝壁的撒狄卫城。阿里斯塔哥拉斯一方联军突入下城，阿尔塔弗涅斯临危不乱，收拢精锐退保山顶卫城死守，将敌挡在绝壁下。混战中芦苇民居失火延烧全城，反困联军于火海；阿尔塔弗涅斯乘乱率守军俯冲反击逼退敌军，神庙被焚亦由此埋下希波大战祸根。"],"history":"公元前四九八年春，小亚细亚爱奥尼亚诸城在米利都僭主阿里斯塔哥拉斯策动下反叛波斯，联雅典等援军翻山突袭吕底亚行省首府撒狄。波斯总督阿尔塔弗涅斯退守撒狄卫城顽强抵抗；下城民居失火延烧全城，阿尔塔弗涅斯乘乱反击逼退联军，随后波斯援兵追败希腊人，埋下希波战争导火索。","sources":"希罗多德·历史·第五卷"},
    "gen_brasidas": {"strategic":["公元前四二二年，雅典与斯巴达鏖战日久，色雷斯重镇安菲波利斯的归属令战火重燃。斯巴达名将巴西达斯此前奇袭夺取该城，扼断雅典造船木材与银矿财源；雅典主战派领袖克里昂亲率重装步兵北上收复失地，逼近城郊山岭，巴西达斯收兵入城待机。"],"tactical":["安菲波利斯三面环河、东筑长墙，地势险固。克里昂率军登城东山脊窥探，见城内寂静便令左翼转身撤回海口待援，不意将步卒未持盾的右侧暴露于城门下。巴西达斯窥破战机，亲率精锐推开南门猛冲敌阵中段，副将自北门杀出夹击；雅典军大溃、克里昂被刺死，巴西达斯亦重伤瞑目，两邦旋即议和。"],"history":"公元前四二二年，雅典主战派领袖克里昂率军北上色雷斯，企图夺回斯巴达名将巴西达斯攻占的重镇安菲波利斯。克里昂抵城外山丘侦察后转身撤回埃昂待援，暴露无盾右侧翼；巴西达斯分自两门突击大破雅典军，克里昂被杀，巴西达斯亦重伤殉国，促成尼西阿斯和约。","sources":"修昔底德·伯罗奔尼撒战争史·第五卷"},
    "gen_cambyses": {"strategic":["公元前五二五年，波斯帝国囊括两河与黎凡特，近东唯剩埃及孤悬尼罗河畔。波斯王冈比西斯二世继父志南征，恰逢埃及海疆盟友倒戈、老法老病逝，普萨美提克三世仓促嗣位。冈比西斯二世借阿拉伯驼队供水越过西奈荒漠，水陆并进直扑埃及东境咽喉佩鲁西姆要塞。"],"tactical":["佩鲁西姆要塞扼守尼罗河东支入海要冲，沼泽沙堤环护，普萨美提克三世集埃及军与雇佣步卒于塞外迎战。两军激战肉搏，埃军在波斯步骑与弓矢轮番冲击下防线崩裂，溃退入城。冈比西斯二世合围猛攻，传闻更于阵前驱赶埃及神兽扰乱守军心神，终克佩鲁西姆要塞，打开征服埃及全境之门。"],"history":"公元前五二五年春，波斯国王冈比西斯二世结好阿拉伯部族供水穿越西奈沙漠，在尼罗河三角洲东门户佩鲁西姆要塞击败新立的埃及法老普萨美提克三世，攻克要塞后顺河陷孟菲斯，灭亡埃及第二十六王朝。异说：波利亚努斯载波斯军阵前驱赶猫犬扰乱守军，希罗多德未载此节。","sources":"希罗多德·历史·第三卷；波利亚努斯·战略"},
    "gen_chabrias": {"strategic":["公元前三七六年，雅典组建海上同盟抗衡斯巴达，斯巴达海军统帅波利斯率舰队封锁近海，截击黑海运粮船，令雅典民食告急。雅典推举名将卡布里亚斯统新造舰队出征；卡布里亚斯护送粮船进港后，主动扬帆进攻纳克索斯，逼波利斯赶来海上决战。"],"tactical":["纳克索斯外海水道宽阔，卡布里亚斯见波利斯舰队来援，即登舰迎敌，自居右翼而命副将统左翼。开战后波利斯猛攻雅典左翼令其濒溃；早已击退当面之敌的卡布里亚斯不贪远追，果断横越海面夹击波利斯本阵。斯巴达舰队反胜为败遭受重创，卡布里亚斯战后妥善打捞落水同胞，一战重夺爱琴海制海权。"],"history":"公元前三七六年九月，斯巴达海军统帅波利斯率舰队封锁爱琴海粮道，雅典名将卡布里亚斯率舰队主动围攻纳克索斯岛诱波利斯决战。海战中雅典左翼受挫，卡布里亚斯及时自右翼分舰驰援反败为胜，重夺爱琴海制海权。注：任务表战场标希马鲁塔，史籍通称纳克索斯海战。","sources":"西西里的狄奥多罗斯·历史丛书·第十五卷；色诺芬·希腊史·第五卷"},
    "gen_chabrias@-357": {"strategic":["公元前三五七年，雅典强征军费激起盟邦不满；在卡里亚君主摩索拉斯煽动与战舰援助下，基奥斯等岛脱离雅典掀起同盟战争。雅典急调陆海重兵扑向叛盟核心基奥斯，宿将卡布里亚斯亲率水师封锁海面，欲突入基奥斯港速战速决。"],"tactical":["基奥斯港湾入口狭窄，港内泊满基奥斯及摩索拉斯助战的战舰。交锋打响，卡布里亚斯令座舰当先冲破封锁闯入内港，后续雅典战舰却畏惧拦击迟疑未进，致其孤舰深陷重围。敌舰四面猛撞刺穿船腹，海水灌舱，水手纷纷跳海逃生；卡布里亚斯耻于弃舰，持盾立于甲板力战阵亡，雅典终被迫承认诸盟邦独立。"],"history":"公元前三五七年，基奥斯、罗得岛等邦在卡里亚君主摩索拉斯策动与舰队援助下反叛雅典，掀起同盟战争。雅典老将卡布里亚斯率水师强攻基奥斯港，座舰率先突入港内而友舰未跟进，遭敌舰合击刺穿进水；卡布里亚斯耻于弃舰，力战殉国。定值：敌方定为卡里亚，敌将取摩索拉斯。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；科尔奈利乌斯·奈波斯·卡布里亚斯传"},
    "gen_datis": {"strategic":["公元前四九〇年，波斯平定爱奥尼亚叛乱后，跨海问罪曾助叛军的埃雷特里亚与雅典。米底老将达提斯统舰队与陆师横越爱琴海，连下诸岛并夷平埃雷特里亚，随即引导大军在马拉松海湾抢滩登陆；雅典将军米太亚德急率公民步阵赶来扼守山口。"],"tactical":["马拉松背海面山，南北沼泽夹束，达提斯背靠战船列阵，以波斯与塞种精锐居中、仆从军居两翼。相持数日后，米太亚德乘波斯骑队调离之隙，督雅典重装步兵跑步猛冲。达提斯中军虽击穿敌军单薄中阵，两翼却先溃散，反遭雅典双翼回旋合围；达提斯突围登舰，绕袭雅典未果，遂引军东归。"],"history":"公元前四九〇年夏末，波斯大流士一世命米底将领达提斯统水陆远征军横渡爱琴海，攻陷埃雷特里亚后登陆阿提卡马拉松湾。对峙数日后，雅典将军米太亚德减薄中军、加厚两翼跑步冲阵；达提斯中军虽击穿雅典中阵，两翼却溃败被合围，波斯军抢船撤退，绕航奇袭雅典未果而东归。","sources":"希罗多德·历史·第六卷"},
    "gen_epaminondas": {"strategic":["公元前三七一年，希腊全境和会上，底比斯代表伊巴密浓达拒绝斯巴达解散彼奥提亚同盟的要求，被剔除出和约。斯巴达即命屯兵边境的国王克勒翁布罗图斯一世越境讨伐，欲摧毁底比斯；伊巴密浓达总揽兵权，率公民军赶赴留克特拉迎截。"],"tactical":["留克特拉平原开阔，克勒翁布罗图斯一世依成规置斯巴达精锐于右翼。伊巴密浓达打破两翼均衡传统，把重步卒与圣队叠成超厚纵列集于左翼，直对斯巴达王本阵；同时令中右翼呈斜线后缩避战。底比斯骑兵先驱散敌骑搅乱步阵，伊巴密浓达随率左翼巨锤猛冲压垮敌右翼，阵斩克勒翁布罗图斯一世，终结斯巴达陆霸。"],"history":"公元前三七一年七月，斯巴达王克勒翁布罗图斯一世借和会决裂攻入彼奥提亚，与底比斯统帅伊巴密浓达会战于留克特拉。伊巴密浓达首创斜线阵，将精锐与圣队厚集左翼猛冲斯巴达右翼本阵，右翼梯次后缩牵制，一举击毙克勒翁布罗图斯一世，终结斯巴达陆上霸权。","sources":"色诺芬·希腊史·第六卷；普鲁塔克·佩洛皮达斯传"},
    "gen_epaminondas@-362": {"strategic":["公元前三六二年，伯罗奔尼撒同盟生变，曼丁尼亚倒向斯巴达与雅典。底比斯统帅伊巴密浓达为护多年霸业，统联军南征，奇袭斯巴达城受阻于老王阿格西劳斯二世后，回师曼丁尼亚谷地寻战；阿格西劳斯二世亦会合雅典等盟军列阵迎敌。"],"tactical":["曼丁尼亚谷地两侧高山夹束，阿格西劳斯二世与盟军横贯谷底列阵。伊巴密浓达先引军至山麓佯装卸甲扎营，诱敌解甲松懈；暗中却将精锐叠成厚列集于左翼，以轻步混编骑队护翼。号角骤响，底比斯左翼如战舰破浪般斜冲凿穿斯巴达防线；联军崩溃之际，伊巴密浓达胸中标枪重伤而逝，希腊自此陷入均势。"],"history":"公元前三六二年夏，因阿卡迪亚同盟分裂、曼丁尼亚联结斯巴达与雅典，底比斯统帅伊巴密浓达率联军南下伯罗奔尼撒，与斯巴达王阿格西劳斯二世等联军决战于曼丁尼亚。伊巴密浓达佯装扎营麻痹敌军，骤以加厚左翼破阵击溃联军，但追击中胸中标枪阵亡，希腊陷入均势。定值：敌将取斯巴达王阿格西劳斯二世。","sources":"色诺芬·希腊史·第七卷；西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "gen_hamilcar": {"strategic":["公元前二四四年，罗马与迦太基争夺西西里岛的第一次布匿战争已苦战二十载，双方国库皆近枯竭。迦太基在陆上节节退缩，全岛仅剩西海岸的莉莉拜乌姆与德雷帕纳两座海港孤城被罗马大军团团围困。","临危受命的年轻统帅哈米尔卡被军士尊称为雷霆巴卡，他此前据守巴勒莫近郊险峰周旋数载令罗马人束手无策；为替被围困的西岸友城分担重压，哈米尔卡作出惊人胆略之举，乘夜率精锐雇佣兵登船潜航西移；","他突然夺占德雷帕纳背后半山腰的厄律克斯古城，与赶来围剿的罗马执政官卡图卢斯所部展开山地对峙。"],"tactical":["厄律克斯山孤耸于西西里西北滨海，形势奇险，山巅神庙驻有罗马守军，山脚平原又扎着罗马大营；哈米尔卡夺占半山古城后恰如楔入两股敌军之间的一枚铁钉，仅凭一条险峻滨海小径维持补给。","在长达两载有余的近身肉搏中，哈米尔卡把山地游击战术发挥得淋漓尽致，一面凭借险坡石垒牢牢顶住上下两面夹攻，一面随时率精悍突击队下山奇袭罗马粮道并出扰意大利海岸，令罗马数任将领损兵折将却无可奈何。","直至罗马公民倾囊捐资重建新式舰队，执政官卡图卢斯先行夺占德雷帕纳港口并在埃加迪群岛海战中击沉迦太基运粮救援船队，厄律克斯山彻底断绝外援；","迦太基元老院授权哈米尔卡全权求和，哈米尔卡严词回绝卡图卢斯要求缴械受辱的条件，最终迫使罗马允许这支从未在陆战中战败的劲旅持械体面登船归国。"],"history":"公元前二四四年，第一次布匿战争后期，迦太基名将哈米尔卡即巴卡率精兵自巴勒莫附近埃尔克特山乘夜跨海奇袭夺取西西里西端罗马控制的厄律克斯山腰古城，将自己夹在山顶罗马守军与山脚罗马大营之间坚守三载。哈米尔卡以神出鬼没的山地袭扰牵制罗马主力，直至公元前二四一年罗马执政官卡图卢斯在埃加迪群岛海战切断海援，哈米尔卡方奉命体面议和撤军。定值：年份取前二四四年、敌将取卡图卢斯。","sources":"波利比乌斯·通史·第一卷；西西里的狄奥多罗斯·历史丛书·第二十四卷"},
    "gen_hamilcar@-240": {"strategic":["公元前二四〇年，刚刚在对罗马大战中割地赔款的迦太基共和国陷入了比外战更为致命的灭顶内祸。从西西里撤回北非的雇佣老兵因军饷被拖欠哗变起事，久受迦太基重税盘剥的利比亚各城邦纷纷响应；","叛军推举斯彭迪乌斯等人为帅，一面围攻北方重港乌提卡，一面扼死迦太基地峡咽喉与巴格拉达斯河下游唯一石桥。迦太基前任主帅汉诺出征惨败，都城陆路完全断绝；","存亡绝续之际，迦太基元老院重新起用西西里名将哈米尔卡，哈米尔卡收编城中公民与新训战象，暗中窥测河口水文风向，筹划一记惊天动地的突围奇谋。"],"tactical":["巴格拉达斯河下游水深泥软，叛帅斯彭迪乌斯在唯一桥梁旁筑起坚城重兵把守，断定迦太基军插翅难越。然而心思缜密的哈米尔卡早已查明，每当海上刮起猛烈东风，海水与河水便会被顶托回流，使入海口水下暗沙浅至可涉而叛军全然不知。","在一个东风呼啸的深夜，哈米尔卡严令全军衔枚疾走，黎明时分踏着半淹水中的河口沙坝神兵天降般渡过巴格拉达斯河，直扑守桥敌营。斯彭迪乌斯大惊失色，急调乌提卡围城叛军与守桥部队两路夹击而来；","面对倍于己方的悍勇叛卒，哈米尔卡故意将前排战象与轻骑后撤，令重步兵装作惊慌退却。斯彭迪乌斯部众以为得计，争先恐后散乱阵形猛追；不料撤退中的迦太基公民方阵骤然依令转身结成铜墙，战象与铁骑同步从两翼反扑，叛军大败亏输，哈米尔卡一战夺回河桥打开平叛大局。"],"history":"公元前二四〇年，第一次布匿战争刚结束，迦太基无力支付军饷引发北非利比亚诸城与雇佣兵全面大起义，叛军首领斯彭迪乌斯封锁迦太基陆路地峡并重兵把守巴格拉达斯河唯一桥梁。临危受命的哈米尔卡观察到强东风能吹退河口潮水露出水下沙坝，乘夜率公民军与战象涉河口奇出敌后，再以精密佯退反冲战术大破斯彭迪乌斯两路合击之军，拯救迦太基危局。","sources":"波利比乌斯·通史·第一卷"},
    "gen_li_xin": {"strategic":["公元前二二五年，三晋既灭、燕国垂危，统一天下的最后障碍只剩南方大国楚国。秦廷殿前议兵之际，老将王翦审度楚境辽阔、民风剽悍，断言非倾尽全国重兵不足以灭楚；","此前率轻骑深入辽东衍水追斩燕太子丹、正值年少气盛的将领李信却慨然出列，豪言何须如此兴师动众，仅凭一军锐卒便足踏平荆楚。雄心勃勃的秦王嬴政大赞李信勇壮，斥王翦老怯，当即拜李信为主将、蒙恬为副，分兵两路南下伐楚。","李信初战果然锋芒夺人，一举攻拔重镇平舆，继而挥师西向横扫鄢郢，随即意气风发调转马头东趋城父准备会合蒙恬直捣楚都寿春，浑然不知楚国名将项燕已在身后张开了罗网。"],"tactical":["城父一带水网平畴相连，远离秦国本土补给基地。李信连战皆捷之下滋生轻敌骄心，以为楚军主力早已闻风丧胆，只顾催动部队长途奔袭赶赴城父会师，既未防备侧后冷箭，亦未修固行军营垒。","岂料楚将项燕故意避开秦军初来锐气，暗中收拢楚地劲旅紧贴在李信行军队列之后，昼夜兼程尾随不舍，一连三日三夜甲不离身。当李信大军长途跋涉抵达城父近郊、将士筋疲力尽正欲安营喘息之时，身后项燕主力骤然擂鼓全线猛扑而上。","楚军以逸击劳、攻势如潮，瞬间冲散秦军外围警戒，接连攻破李信两处大营，接连阵斩秦军诸位都尉；秦师阵脚崩溃，一败涂地，李信无力收拢残局，只得率余部仓皇逃回秦境请罪。经此惨痛教训，秦王嬴政亲赴频阳向王翦谢过，改以举国之兵稳步图楚。"],"history":"公元前二二五年，曾在灭赵、伐燕衍水之战中立下奇功的秦少壮名将李信深受秦王嬴政器重。议伐楚时王翦力主倾国重兵，李信自请轻兵锐卒即可破楚，秦王大悦，命李信与蒙恬分路南征。李信初战大破楚军于平舆，又西破鄢郢，引兵东向与蒙恬会师城父途中，遭楚大将项燕尾随三日三夜突袭，连失两壁、折损七都尉而大败奔还；秦王遂亲请王翦复出灭楚。","sources":"史记·白起王翦列传；资治通鉴·秦纪一"},
    "gen_li_xin@-226": {"strategic":["公元前二二六年，因前一年燕国太子丹派刺客荆轲献图咸阳行刺未遂，盛怒之下的秦王嬴政增发重兵猛攻燕国，先在易水西岸击溃燕代联军，继而一举攻陷燕国故都蓟城。","燕王喜与主战首脑太子丹不肯坐以待毙，收拢燕国残存精锐车骑仓皇向东北逃往苦寒偏远的辽东襄平，妄图凭借辽西走廊与大河天险负隅顽抗、苟延国祚。","为彻底铲除行刺祸首，当时正随王翦北征、血气方刚的秦国少壮猛将李信主动请缨，仅挑选一枝精悍轻装骑步锐卒脱离大军辎重，顶着塞北寒风跨越山海险道，一路衔尾疾追太子丹直扑辽东衍水。"],"tactical":["衍水奔流于辽东群山与平原之间，河水冰寒刺骨，两岸芦苇荒洲密布，太子丹统领燕国东撤主力在此依水设防，以为秦军大队刚克蓟城绝难迅速远追至此。不料李信治军最善长途奔袭，麾下秦国轻骑昼夜换马疾驰，如神兵天降般突然杀抵衍水岸边，不等燕军稳固壁垒便迎面发起狂飙猛冲。","燕军本就是惊弓之鸟，在李信身先士卒的凶悍突击下防线顷刻崩裂，将士死伤溃散无数，太子丹走投无路只得潜逃藏匿于衍水河洲草泽之中。随着衍水防线被李信一战踏碎，辽东襄平直接暴露于秦骑铁蹄之下；","惊恐绝望的燕王喜听信代王嘉献计，派使者搜出亲生儿子太子丹残忍斩首，捧着首级献给李信军前乞求缓师，李信携大功凯旋归报咸阳，一时深得秦王嬴政宠信。"],"history":"公元前二二七年燕太子丹遣荆轲刺秦王嬴政未遂，秦王震怒命王翦伐燕破易水联军。公元前二二六年十月秦军攻拔燕都蓟城，燕王喜与太子丹率残余精兵东走辽东。秦少壮将领李信亲率精锐轻骑跨越辽西走廊穷追不舍，在辽东衍水即今太子河大破太子丹殿后主力，逼得燕王喜斩杀太子丹首级献秦乞和，李信以此奇功跃居秦廷新锐名将。","sources":"史记·白起王翦列传；史记·刺客列传；资治通鉴"},
    "gen_lysander": {"strategic":["公元前四〇五年，伯罗奔尼撒战争进入决胜关头。斯巴达统帅吕山德借波斯财力重建舰队，乘虚攻占海峡重镇兰普萨库斯，掐断雅典黑海粮道；雅典将领科农等倾最后家底率舰队追入海峡，泊于对岸荒僻的羊河滩头，急欲逼吕山德决战。"],"tactical":["羊河河口仅为开阔沙石滩涂，无港无粮。科农等连日横渡海峡列阵邀战，吕山德令全军披甲登船却拒不出港，待敌返航后派快船尾随侦察。数日后雅典将士骄怠，收兵回滩便任水手散入内陆觅食；吕山德见侦察船举铜盾反光传讯，立挥全舰队疾渡突袭空滩，尽俘敌舰，唯科农乘快舰突围，雅典自此绝粮倾覆。"],"history":"公元前四〇五年秋，斯巴达统帅吕山德攻占赫勒斯滂海峡重镇兰普萨库斯以断雅典黑海粮道，雅典将领科农等率舰队泊于对岸无港口的羊河海滩。吕山德连日坚拒邀战麻痹敌军，第五日趁雅典水手离船登岸觅食，率全舰队闪电横渡突袭，几乎全歼雅典海军，科农仅率少数快舰逃往塞浦路斯。","sources":"色诺芬·希腊史·第二卷；普鲁塔克·吕山德传"},
    "gen_lysander@-395": {"strategic":["公元前三九五年，斯巴达战后专横激起诸邦公愤，底比斯领袖伊斯梅尼亚斯借波斯资助联雅典抗命。名将吕山德力劝斯巴达发兵，定南北两路合击之策；吕山德先行北赴福基斯纠集盟军，按期进抵要冲哈利亚托斯城外，准备会攻伊斯梅尼亚斯一方。"],"tactical":["哈利亚托斯地处湖岸山麓要道。吕山德抵城下久候南路援军不至，不知信使已被截获，遂轻率领军逼近城墙试图劝降强攻。岂料伊斯梅尼亚斯一方的底比斯先头部队已入城设防，城外援军又自山后疾驰杀到；城门骤开，底比斯步骑内外夹击未及成阵的斯巴达军，吕山德混战阵亡，科林斯战争全面爆发。"],"history":"公元前三九五年，底比斯领袖伊斯梅尼亚斯联雅典挑起科林斯战争。斯巴达定南北夹击之策，吕山德率北路联军先抵哈利亚托斯，因联络信使被截，未等南路斯巴达王赶到便逼近城墙，遭城内守军与赶来的底比斯主力前后夹击阵亡。定值：敌将估算取底比斯主战领袖伊斯梅尼亚斯。","sources":"色诺芬·希腊史·第三卷；普鲁塔克·吕山德传"},
    "gen_lysander@-406": {"strategic":["公元前四〇六年，斯巴达命善谋的吕山德执掌海军驻节以弗所，结好波斯王子提高军饷以招徕熟练桨手。雅典统帅亚西比德进驻对岸诺提姆海角监视，因筹饷暂赴外地，严令留守舵手安提奥库斯不得主动求战；吕山德闭港整训，静待敌军破绽。"],"tactical":["诺提姆海角与以弗所隔湾相望。贪功的安提奥库斯违背禁令，驾座舰率快船划至以弗所港嘴叫阵诱敌；吕山德看穿其孤进，先遣快舰扑出撞沉安提奥库斯座舰并将其击毙。见其余雅典战舰未及编队便零散来救，吕山德立挥全舰队整列迎击，重挫敌军；雅典由此迁怒罢免亚西比德，自毁海上栋梁。"],"history":"公元前四〇六年春，斯巴达海军统帅吕山德驻节以弗所，借波斯增饷厚募水手，与驻诺提姆海角的雅典舰队对峙。雅典主帅亚西比德暂离前线并严令代理指挥安提奥库斯不得出战，安提奥库斯违命赴港前诱敌；吕山德精准反击击沉其座舰并击败赶来的雅典舰群，致使亚西比德遭罢黜。定值：敌将取安提奥库斯。","sources":"色诺芬·希腊史·第一卷；普鲁塔克·吕山德传"},
    "gen_miltiades": {"strategic":["公元前四九〇年，波斯统帅达提斯攻灭埃雷特里亚后横渡海峡，登陆马拉松平原，雅典面临灭顶之灾。斯巴达援军囿于月圆之忌未发，仅有普拉提亚倾城来助。熟知波斯战法的将军米太亚德力排畏战之议，说服执政官主战，率希腊方阵进驻山麓封死要道。"],"tactical":["马拉松平原东临海湾、西倚群山，米太亚德据山坡扎营以避波斯骑锋。及至轮掌帅印之日，侦知达提斯分调骑队，米太亚德果断削薄中军、厚集两翼与敌等宽，令重甲公民疾奔穿过箭雨猛撞敌阵。雅典中军虽退，厚重的两翼却撕碎敌翼并向内合围波斯中坚；米太亚德破敌后急行回防雅典，逼退达提斯舰队。"],"history":"公元前四九〇年九月，波斯统帅达提斯率远征军登陆马拉松平原，雅典诸将战和不一，熟谙波斯战法的将军米太亚德力主出城迎敌，与普拉提亚盟军据山扼守。轮值主帅之日，米太亚德减薄中军、厚集两翼疾奔冲锋，两翼包抄击溃波斯军，随后强行军回防雅典逼退波斯舰队。","sources":"希罗多德·历史·第六卷；科尔奈利乌斯·奈波斯·米太亚德传"},
    "gen_parmenion": {"strategic":["公元前三三四年，马其顿大举东征波斯，辅佐两代君主的老帅帕曼纽此前已率前遣军在小亚细亚立足，主力渡海会师后出任全军副帅。波斯诸总督拒纳客将门农清野退守之策，纠集铁骑与门农所部雇佣步卒重防格拉尼库斯河渡口，帕曼纽遂辅佐国王整军东进。"],"tactical":["格拉尼库斯河底多乱石、东岸高耸泥泞，波斯骑队密布河沿，门农雇佣步卒列于后岗。帕曼纽审视地势进言次日破晓济河，国王决意即日强攻，命帕曼纽统左翼色萨利铁骑与左部方阵。开战后右翼猛攻吸引敌主力，帕曼纽沉着调度色萨利骑队结菱形阵涉急流抢登东岸，压垮当面敌骑，配合右翼合歼雇佣步阵，旗开得胜。"],"history":"公元前三三四年五月，马其顿元勋老帅帕曼纽以全军副帅随亚历山大渡海伐波斯。格拉尼库斯河畔对阵波斯诸总督与门农时，帕曼纽建议次日拂晓济河未果，受命统率全军左翼色萨利及盟邦骑步兵涉水强攻，稳健压制波斯右翼，配合右翼合击大破波斯军。","sources":"阿里安·亚历山大远征记·第一卷；西西里的狄奥多罗斯·历史丛书·第十七卷"},
    "gen_parmenion@-331": {"strategic":["公元前三三一年秋，马其顿远征军渡过底格里斯河，在开阔平坦的高加米拉原野迎来了与波斯国王大流士三世的终极决战。年近七旬的副帅帕曼纽随军转战亚洲数载，战前夜登高俯瞰原野上无边无际的波斯营火，忧心白昼交锋己方寡不敌众、侧翼被包；","他遂入帐建议趁黑夜奇袭敌营，亚历山大却坚持白昼堂堂决胜。次日天明列阵，帕曼纽恪尽职守披甲登上左翼帅位，统领色萨利骑队、希腊盟军骑兵与左翼方阵，在毫无山海屏障的茫茫平畴之上独自迎向波斯右翼排山倒海的铁骑洪流。"],"tactical":["高加米拉平原尘土遮天，随着右翼亚历山大率部不断向右斜移寻找战机，留在原地的帕曼纽左翼承受了难以想象的正面与侧包重压。大流士三世麾下名将马扎亚斯统领着人数数倍于敌的亚美尼亚、卡帕多细亚与叙利亚重骑，从正面和外翼同时猛扑帕曼纽防线；","更凶险的是，中路方阵因前移脱节裂开一道缺口，一股波斯与印度精骑趁机直穿马其顿大阵杀入后方辎重营，前后夹击令左翼岌岌可危。","白发苍苍的帕曼纽毫无退缩，一面急调二线预备步卒回身肃清劫营敌骑，一面派快马追报亚历山大告急，自己则率色萨利铁骑在血泊中反复冲杀堵口，寸步不让。","待亚历山大在右路吓走大流士三世、勒马回师增援之时，帕曼纽麾下将士甚至已凭死斗稳住战局并转入反攻，两部合击将绝望死战的波斯残骑彻底粉碎；这场悲壮坚守亦成为老帅帕曼纽一生戎马的最后辉煌。"],"history":"公元前三三一年十月高加米拉决战前夜，老帅帕曼纽虑敌众我寡建议夜袭，亚历山大拒之。决战当日帕曼纽统率马其顿左翼，面对大流士三世右翼统帅马扎亚斯指挥的叙利亚、米底与亚美尼亚优势铁骑围攻，外加波斯骑兵穿阵劫掠后营之乱，年届七旬的帕曼纽浴血苦撑并派骑向亚历山大求援，死死稳住左翼直至亚历山大击败大流士三世后回援破敌，完成戎马生涯巅峰绝唱。","sources":"阿里安·亚历山大远征记·第三卷；普鲁塔克·亚历山大传"},
    "gen_parmenion@-333": {"strategic":["公元前三三三年深秋，马其顿东征大军穿过奇里乞亚南进叙利亚门户之际，御驾亲征的波斯国王大流士三世突然率浩荡王师自北方山道插至马其顿后方重镇伊苏斯，截断远征军退路与补给线。老帅帕曼纽此前已奉命抢占通往叙利亚的沿海山门，闻变立即与回师北返的亚历山大会合。","行军至伊苏斯南口狭窄滨海走廊，大流士三世已隔皮纳罗斯河严阵以待；亚历山大将右翼突击重任留给自己，而把紧贴大海、直面波斯主力铁骑冲击的左翼防线托付给最信赖的宿将帕曼纽，全军胜败全系于左翼能否在强敌猛压下屹立不倒。"],"tactical":["伊苏斯海滨滩岸狭窄，大流士三世因山麓地势崎岖难容马队，便把波斯最骁勇善战的披甲重骑尽数调往临海的波斯右翼，企图依仗绝对数量优势一举踏碎帕曼纽防线。","亚历山大临战再三叮嘱帕曼纽务必紧贴海浪边缘列阵，绝不给波斯骑兵绕海包抄的一丝缝隙，更临时将精锐色萨利骑队自右翼悄悄从阵后移调至帕曼纽麾下增援。交锋未几，大批波斯铁骑便涉过河口浅滩，如狂涛骇浪般扑向帕曼纽左翼；","帕曼纽须发皆张，亲临前线沉着调度色萨利骑队以退进自如的机动反复反冲，率领左翼步骑寸土必争、死战不退，硬生生将汹涌的波斯骑潮死死钉在海滩一线。直到右翼亚历山大冲破山麓防线直逼波斯王车、吓走大流士三世，苦战良久的波斯右翼骑兵惊见国君已逃方才溃退；","帕曼纽当即挥动色萨利铁骑全速追杀，完美筑就了锤砧战术中稳如泰山的铁砧之功。"],"history":"公元前三三三年十一月伊苏斯会战中，波斯王大流士三世将最精锐的波斯铁骑集中于临海右翼，企图沿海岸击穿马其顿左翼包抄全军。马其顿副帅帕曼纽受命统领左翼，严格执行紧贴海岸不留空隙之令，率色萨利与伯罗奔尼撒骑兵顶住数倍波斯重骑的轮番猛冲，充当全军坚不可摧的铁砧，直至右翼亚历山大击走大流士三世回师夹击，共创伊苏斯大捷。","sources":"阿里安·亚历山大远征记·第二卷；西西里的狄奥多罗斯·历史丛书·第十七卷"},
    "gen_philip_ii": {"strategic":["公元前三三八年，马其顿王腓力二世练成强悍方阵与骑队，借调停神庙纷争越温泉关南下，进占中希腊咽喉。面对征服危机，雅典与底比斯捐弃前嫌结盟；底比斯猛将特阿格尼斯统圣队会合联军封锁喀罗尼亚平原，腓力二世遂挥师迎上决战。"],"tactical":["喀罗尼亚平原北临河泽、南倚高丘，联军左翼雅典兵靠山，右翼特阿格尼斯统底比斯军贴河严守。腓力二世坐镇右翼，看准雅典兵急躁贪功，故意整队后退；雅典兵果真盲追，致联军防线豁开缺口。马其顿左翼骑队乘隙刺入包抄底比斯侧背，腓力二世亦反冲溃雅典军；特阿格尼斯率圣队死战殉国，希腊诸邦尽皆俯首。"],"history":"公元前三三八年八月，马其顿王腓力二世率军南下中希腊，雅典与宿敌底比斯结盟迎抗，底比斯名将特阿格尼斯统圣队居联军右翼。决战于喀罗尼亚平原时，腓力二世右翼佯退诱雅典左翼脱节，王子亚历山大乘隙突破缺口，合围全歼特阿格尼斯所率底比斯圣队，确立马其顿全希腊霸权。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；普鲁塔克·亚历山大传"},
    "gen_philip_ii@-352": {"strategic":["公元前三五二年，福基斯统帅奥诺马库斯强占德尔斐神庙熔金募兵，北上介入色萨利战事，前一年曾凭石弩两挫马其顿王腓力二世。腓力二世退归蓄力后重整南下，团结色萨利诸邦进逼帕加塞海港，迫使北救的奥诺马库斯在番红花原决战。"],"tactical":["番红花原紧邻帕加塞海湾，原野平阔。腓力二世命全军头戴象征神罚的月桂冠列阵，以长矛方阵正面咬住敌阵，同时投入伙伴骑队与色萨利铁骑猛击两翼。优势铁骑迅速撕碎敌翼席卷后背，奥诺马库斯麾下雇佣军崩溃，争相弃甲跳海游向外海盟舰；奥诺马库斯溺亡海中，马其顿自此执掌色萨利。"],"history":"公元前三五二年，第三次神圣战争中，福基斯统帅奥诺马库斯熔德尔斐神庙金银募军，前一年曾两败马其顿王腓力二世。腓力二世重整再入色萨利，命全军头戴阿波罗月桂冠，会合色萨利骑兵在帕加塞湾畔番红花原包抄击溃福基斯军，奥诺马库斯投海溺亡，腓力二世遂掌色萨利霸权。","sources":"西西里的狄奥多罗斯·历史丛书·第十六卷；查士丁·腓力史概要"},
    "gen_seleucus_i": {"strategic":["公元前四世纪末，曾在巴比伦白手复国的塞琉古已将伊朗高原至中亚的东方各行省尽收麾下，唯独西方老对手安提柯一世依然虎视眈眈，不仅自封为王，更派子德米特里横扫希腊，企图独吞整个亚历山大遗产。","当马其顿与色雷斯盟友发来紧急求援信函时，塞琉古审时度势，当机立断与东邻印度孔雀王朝缔结姻亲和约，主动让出印度河边地，换回一支足以改写西方战局的庞大印度战象部队。","公元前三〇二年冬至次年春，塞琉古率东方精兵与战象群冒严寒穿越卡帕多细亚高原，及时与苦撑待援的利西马科斯大军会合，进抵弗里吉亚的伊普苏斯平原，与安提柯一世主力正面对垒。"],"tactical":["伊普苏斯原野无遮无拦，塞琉古与利西马科斯并肩列开马其顿方阵，将部分战象置于前线抵消敌象，更把大批机动战象与东方轻骑握在手中充作预备杀招，命年轻的王子安条克统领左翼骑兵迎战敌方右翼。","开战未久，安提柯之子德米特里率重骑猛冲联军左翼，安条克所部不支后撤，德米特里乘胜策马远追脱离主战场。坐镇全局的塞琉古抓住了这一转瞬即逝的战机，当即挥动预备战象群横切入德米特里与安提柯一世方阵之间的空隙；","受惊的马群闻到陌生的巨象气息寸步难前，德米特里被死死挡在战局之外。塞琉古并未驱兵硬撞安提柯厚重方阵，而是令轻装弓骑环绕其裸露右翼反复驰射威慑，动摇敌卒军心直至前阵瓦解，安提柯一世在标枪雨中战死。","此役过后盟国瓜分故地，塞琉古尽得叙利亚膏腴之土并营建新都安条克，奠定塞琉古帝国的宏大规模。"],"history":"公元前三〇一年，东方继业者国王塞琉古在完成与印度孔雀王朝和约、获得大批印度战象后，翻越亚美尼亚山地进入小亚细亚与盟友利西马科斯会师，在伊普苏斯平原与安提柯一世父子决战。面对德米特里骑兵突破，塞琉古果断调度战象群横截战场隔断安提柯父子联系，再以骑射威逼瓦解安提柯本阵，击毙安提柯一世，一举囊括叙利亚广袤疆土。","sources":"普鲁塔克·德米特里传；阿庇安·叙利亚战记"},
    "gen_seleucus_i@-281": {"strategic":["公元前二八一年，距离亚历山大辞世已逾四十载，当年叱咤风云的众位继业者仅剩东方霸主塞琉古与兼领色雷斯、马其顿及小亚细亚的利西马科斯两位白发老王尚在人间。原本并肩破敌的两位盟友，因利西马科斯晚年宫廷惨剧彻底决裂；","利西马科斯听信王后构陷毒杀贤明王储阿加托克利斯，储君遗孀携臣属东逃向塞琉古求援，帕加马等小亚细亚重镇亦纷纷来投。","年届七旬有余的塞琉古见一统亚历山大旧疆的最后良机降临，当即统率塞琉古帝国大军西越托罗斯山脉直入吕底亚，利西马科斯亦急渡海峡东来迎堵，两位老帅在库鲁佩迪安原野迎来了继业者时代的终章对决。"],"tactical":["库鲁佩迪安平原横卧于萨第斯北境河谷，寒冬朔风凛冽，两位年逾古稀的马其顿老将各自披挂上阵，统领着同源同种的萨里沙长矛方阵与铁骑正面相撞。利西马科斯麾下将士本就因王储冤死而人人自危、士气低迷，面对塞琉古挟大义之名与战象精骑发起的雷霆攻势，防线很快在激战中动摇崩解。","塞琉古亲自督军步步紧逼，冲散利西马科斯侧翼护卫；尽管年迈的利西马科斯仍不减当年随亚历山大搏狮的悍勇，在乱军中挥剑死战不退，终被一名赫拉克利亚标枪手掷枪刺穿胸膛，倒毙于沙场之上，唯有忠犬守尸不去。","此战塞琉古一举囊括小亚细亚全境，成为继亚历山大之后几乎重统全帝国的胜利者，继业者混战时代至此画上句号。"],"history":"公元前二八一年二月，亚历山大麾下最后两位在世的年近八旬老帅塞琉古与色雷斯兼马其顿国王利西马科斯反目开战。此前利西马科斯听信后妻谗言处死贤能长子阿加托克利斯，导致帕加马等小亚细亚诸城纷纷叛投塞琉古。塞琉古亲率大军翻越托罗斯山脉西进吕底亚，在萨第斯以北的库鲁佩迪安平原击败利西马科斯，利西马科斯被标枪刺死，塞琉古赢下继业者时代最后一战。","sources":"阿庇安·叙利亚战记；查士丁·腓力史概要·第十七卷；门农·赫拉克利亚史"},
    "gen_seleucus_i@-309": {"strategic":["公元前三一一年，曾在加沙立功的塞琉古凭托勒密拨给的精简小队冒险东返，靠昔日善政深得巴比伦民心；他一路招揽旧部重夺故地，并在底格里斯河畔奇袭大破安提柯派来的东方总督大军，一举收复米底与苏萨。","眼看后院燃起滔天大火，正在西方与诸王停战的独眼霸主安提柯一世怒不可遏，亲自统领主力大军杀回美索不达米亚，与塞琉古围绕巴比伦城垣、河渠与乡野展开长达两载的惨烈拉锯。","至公元前三〇九年盛夏，两军在巴比伦郊野再度主力相对，首日鏖战至天黑仍难分胜负，一场决定东方归属谁手的生死智斗在夜幕中悄然展开。"],"tactical":["巴比伦郊野河网密布，夏日白昼酷热难当，首日血战罢兵后，安提柯一世麾下将士疲惫不堪，纷纷卸下沉重铠甲与盾牌倒头酣睡。塞琉古却深知正面拼耗难胜兵多将广的安提柯一世，唯有出奇制胜方能一锤定音，遂暗令全军将士穿戴整齐甲胄、手执兵器就地假寐，并在夜半之后悄然饱餐列队。","趁东方微露曙光、旷野尚笼罩在晨雾昏暗之际，塞琉古亲率全副武装的精兵不吹号角悄然逼近敌营，抵近营门方才齐声发喊猛冲而入。安提柯大营一片惊惶，士卒赤身空手从睡梦中惊醒，来不及寻甲执矛便被塞琉古长矛手与铁骑砍翻在地，全军溃不成军。","安提柯一世损兵折将，彻底断了收复东方的念头，狼狈引军西撤叙利亚；塞琉古自此稳掌从两河直至中亚的辽阔疆土，塞琉古帝国昂然屹立。"],"history":"公元前三一一塞琉古自埃及率轻骑重返巴比伦复国，引发与亚洲霸主安提柯一世长达三年的巴比伦战争。安提柯一世携子德米特里亲率主力攻入巴比伦尼亚，双方在城内外反复拉锯至公元前三〇九年夏；塞琉古在最后决战中假令士卒夜间卸甲安歇，黎明前突然全副武装猛扑尚未起床披甲的安提柯大营，大败安提柯一世，迫使其彻底放弃东方诸省，奠定塞琉古帝国基业。","sources":"巴比伦继业者编年史；波利亚努斯·战略·第四卷"},
    "gen_themistocles": {"strategic":["公元前四八〇年，波斯水陆大军越海峡南下侵希，北希腊望风归附。雅典将领地米斯托克利早年力主用银矿收益大造战舰，此时更谦让海军名义帅位以团结诸邦。依水陆联防之策，陆军守温泉关，地米斯托克利则率联合舰队进驻阿尔特米西昂，迎堵阿凯门尼斯的波斯舰队。"],"tactical":["阿尔特米西昂扼优卑亚岛北端水道，风急礁多。阿凯门尼斯所在的波斯舰队规模占优，并遣分舰队绕航外海包抄。地米斯托克利稳住军心，先结环形阵诱敌围拢再四向猛撞重创敌舰，当夜风暴又摧毁波斯绕航船队；次日波斯排半月阵强攻，双方浴血平分秋色。闻温泉关失陷，地米斯托克利遂有序南撤保存主力。"],"history":"公元前四八〇年夏末，波斯水陆大军侵希，雅典领袖地米斯托克利率希腊联合舰队配合温泉关陆军，扼守优卑亚岛北端阿尔特米西昂水道，与阿凯门尼斯等统率的波斯舰队连日激战。波斯绕航分舰队遇风暴覆没，正面海战互有损伤；因温泉关失守，地米斯托克利率舰队有序南撤萨拉米斯。定值：战场定为阿尔特米西昂。","sources":"希罗多德·历史·第八卷；普鲁塔克·地米斯托克利传"},
    "gen_themistocles@-480": {"strategic":["公元前四八〇年秋，波斯王薛西斯一世突破温泉关焚毁雅典空城，退泊萨拉米斯岛的盟邦诸将惊惶欲撤往地峡。雅典统帅地米斯托克利深知退入外海必遭吞没，力逼盟军留守；他又暗遣家仆向薛西斯一世诈报希腊人内讧将逃，诱波斯舰队连夜驶入萨拉米斯海峡。"],"tactical":["萨拉米斯海峡曲折逼仄，薛西斯一世登山观战，波斯水手连夜封锁出口疲惫不堪。天明后地米斯托克利令战舰佯退，引敌深入最窄湾口；待晨风掀浪使笨重的波斯船群摇晃纠缠，希腊灵巧战舰乘风猛冲，以铜角撞碎敌船侧舷。波斯前舰欲退而后舰前挤，全军惨败，薛西斯一世被迫率主力退回小亚细亚。"],"history":"公元前四八〇年九月，温泉关失陷、雅典被焚后，希腊联合舰队退集萨拉米斯海峡。盟邦诸将欲退守科林斯地峡，雅典统帅地米斯托克利力争留战，密遣仆人向波斯王薛西斯一世诈报希腊人将逃，诱波斯舰队连夜驶入狭窄水道，天明借涌风与地形大破波斯海军，扭转希波战局。","sources":"希罗多德·历史·第八卷；埃斯库罗斯·波斯人"},
    "guyashu_shamushi": {"strategic":["约公元前一七九六年，两河流域城邦林立，诸王竞逐商道与沃土。沙姆希阿达自底格里斯河上游崛起，唯西南方向受制于控扼幼发拉底河商路的马里王国。马里王亚赫敦林屡与亚述争锋，未几马里宫廷突发变乱。沙姆希阿达乘机亲统亚述大军顺河南下，兵锋直逼幼发拉底河畔马里。"],"tactical":["马里城背倚幼发拉底河干流，凭人工运河与厚重土砖城垣构筑防线，亚赫敦林一方据城待援。沙姆希阿达进抵外围后，先分兵弹压沿河诸镇，截断游牧援军通道，随即沿运河堤岸合围猛攻。孤城人心瓦解，亚述军破城而入，亚赫敦林败亡；沙姆希阿达留子镇守马里，上两河自此联为一统。"],"history":"约公元前一七九六年，上美索不达米亚霸主沙姆希阿达乘幼发拉底河中游重镇马里内乱之机，进军占领马里，置幼子镇守，构建起横跨上两河的古亚述疆域。异说与史料不足：马里泥板载马里王亚赫敦林先死于宫廷侍从刺杀，其子短暂继位后亚述夺取马里，定稿表取名王亚赫敦林为守方代表；攻城具体细节泥板阙载。","sources":"马里王室泥板文书；亚述王表"},
    "guyashu_tigelate": {"strategic":["公元前七三二年，新亚述帝国凭常备军制大举经略地中海东岸。亚兰国王利汛不甘纳贡，联以色列结成反亚述同盟，出兵围攻拒不入盟的犹大王国。亚述王提格拉特应犹大求援南下，先扫荡沿海断埃及外援，再席卷以色列北境剪除羽翼，回师合围孤立无援的大马士革。"],"tactical":["大马士革坐落反黎巴嫩山东麓绿洲，巴拉达河环绕，城坚林密，利汛败退入城闭门死守。提格拉特不急于蚁附硬攻，先扫平周边属邑、砍伐果园断其生计，再筑围墙土山以攻城槌反复猛撞。久困之下城内粮尽防溃，亚述军破城擒杀利汛，废亚兰改置行省，叙利亚诸邦尽数俯首。"],"history":"公元前七三二年，新亚述国王提格拉特应犹大王亚哈斯求援，继扫荡腓尼基与以色列北境后，主力合围反亚述同盟首脑亚兰国王利汛的都城大马士革。经严密围困与摧毁城外园林属邑，亚述攻破大马士革，处死利汛，将亚兰故地改置为亚述行省，终结了亚兰大马士革王国。","sources":"提格拉特帕拉沙尔三世铭文；列王纪下·第十六章"},
    "hekaniya_artabazos": {"strategic":["公元前三三〇年，阿契美尼德波斯帝国已走到山穷水尽的最后时刻，高加米拉惨败与波斯波利斯陷落后，大流士三世一路向东退往伊朗高原深处。随行重臣之中，早年曾旅居马其顿宫廷、历经三朝的老臣阿尔塔巴佐斯始终对波斯王室忠心耿耿；","当巴克特里亚总督贝苏斯等人阴谋发动兵变劫持并杀害大流士三世时，阿尔塔巴佐斯义不从贼，毅然带领诸子与效忠王室的希腊雇佣军脱离叛党，转道退入里海南岸崇山密林环绕的赫卡尼亚行省。","此时马其顿王亚历山大已为大流士三世风光发葬，旋即调转兵锋翻越险峻山岭杀入赫卡尼亚，兵临重镇兹拉卡塔，以扫清残存的波斯抵抗力量。"],"tactical":["赫卡尼亚北临里海，南障高耸入云的厄尔布尔士山脉，关隘幽深、林莽蔽日，首府兹拉卡塔坐落于山麓肥沃谷地之中。","亚历山大为防山中波斯旧部与强悍的塔普里、马尔迪山地部族合流阻截，将马其顿远征军分为三路穿山并进，自率轻装精锐攀越绝险小径，一路击破沿途山民依托密林与山崖布下的阻击防线，会师进驻兹拉卡塔。","退保赫卡尼亚群山间的阿尔塔巴佐斯目睹马其顿大军如入无人之境，加之故主已死、篡逆贝苏斯不义，深知凭孤掌残兵绝难挽回波斯国祚。这位须发皆白的波斯老帅遂放下刀兵，携九名儿子亲赴兹拉卡塔大营会见亚历山大；","亚历山大感念昔日宫廷旧谊及其忠义气节，亲自下马搀扶礼遇，留用其父子重臣，残余希腊雇佣军亦相继缴械，里海南岸自此彻底平定。"],"history":"公元前三三〇年夏，波斯末代国王大流士三世在东逃途中遭叛臣贝苏斯弑杀，唯白发老臣阿尔塔巴佐斯率家族及希腊雇佣兵坚守忠节，脱离叛党退入里海南岸山林险峻的赫卡尼亚。马其顿王亚历山大率军翻越厄尔布尔士山脉平定山地部族进驻首府兹拉卡塔，年迈的阿尔塔巴佐斯见阿契美尼德天命已终，率诸子与雇佣军赴营体面归附，获亚历山大隆礼优待。","sources":"阿里安·亚历山大远征记·第三卷；库尔提乌斯·亚历山大大帝史"},
    "hesitiya_yiasong": {"strategic":["公元前三七四年，中南希腊诸强缠斗正酣，北方费莱僭主伊阿宋已练成精悍雇佣军与铁骑，统一色萨利全境并获举为最高统帅。伊阿宋志在问鼎全希霸权，统劲旅越温泉关南向经略福基斯与圣地德尔斐；雅典等邦震动，福基翁一方依托山地险隘严阵戒备。"],"tactical":["德尔斐外围山峦耸峙，谷道崎岖，不利重骑冲锋，福基翁一方抢占山口高地据险设防。伊阿宋疾行抵近，审知仰攻坚隘必损精锐，遂发挥轻盾步卒与色萨利骑队机动迅捷之长，分兵扫荡外围邑落与要道实施武力慑压。守军困于险隘不敢野战，被迫在通道事务上妥协；伊阿宋打通南下走廊后全师北还，威震希腊。"],"history":"公元前三七四年前后，色萨利最高统帅伊阿宋统一色萨利全境后率精锐骑兵与雇佣军南下经略福基斯与圣地德尔斐周边，震动希腊诸邦。史料不足与定值：色诺芬等载伊阿宋南下经略福基斯并觊觎德尔斐祭典主导权，古典史料未载守方主将，定稿表取雅典将领福基翁为代表，播报概括扼险对峙。","sources":"色诺芬·希腊史·第六卷；西西里的狄奥多罗斯·历史丛书·第十五卷"},
    "heti_muwatali": {"strategic":["公元前一二七四年，赫梯帝国雄踞小亚细亚，视奥龙特斯河流域为南疆屏障。埃及法老拉美西斯即位后经略迦南，诱使赫梯藩属阿穆鲁背盟投埃，率大军北图卡迭石。赫梯王穆瓦塔利深知卡迭石有失则北叙利亚尽摇，遂征集本部与盟邦兵马倾力南下，提前进抵卡迭石城外布阵待敌。"],"tactical":["奥龙特斯河绕过卡迭石城垣，城东平地便于战车藏匿。穆瓦塔利隐主力于城背，遣牧人诈降诱拉美西斯孤军渡河安营；待埃军前后脱节，即令战车涉浅冲散埃军次队并杀入王营。惜车兵贪掠财货致攻势受阻，遭埃军援兵反扑退回东岸。次日拉美西斯引兵南撤，穆瓦塔利乘势收复阿穆鲁，稳固南疆霸权。"],"history":"公元前一二七四年五月，赫梯国王穆瓦塔利纠合帝国与属邦兵力南下叙利亚，在奥龙特斯河畔卡迭石设伏迎击埃及法老拉美西斯。穆瓦塔利遣人诈降诱使埃军前锋孤军深入，发重型战车渡河冲垮埃军队列并围攻法老营垒；因车兵贪掠辎重且埃军援兵赶到未能全歼对手，但成功迫使埃军撤退，稳保叙利亚霸权。","sources":"哈图沙泥板文书；卡迭石铭文"},
    "jialedi_nibujianisa": {"strategic":["公元前五八七年，新巴比伦与埃及激烈争夺黎凡特走廊。巴比伦王尼布甲尼撒亲手册立的犹大王西底家受亲埃贵族怂恿，撕毁盟誓拒纳贡赋，暗引埃及北援。尼布甲尼撒决不容西南门户失控，统大军扫平犹大外围据点，将主力合围至西底家据守的都城耶路撒冷。"],"tactical":["耶路撒冷雄踞犹大山地脊梁，三面深谷险峻，唯北面稍缓，西底家凭坚厚石墙闭门待援。尼布甲尼撒环城筑垒严密封锁，中途分兵击退北上的埃及援军，断绝守军外援。久困之下城内饥疫交加，巴比伦军撞破北墙缺口杀入城中，追骑擒获夜逃的西底家，拆城墙焚圣殿，犹大王国就此覆亡。"],"history":"公元前五八九年至前五八七年，犹大王西底家背叛新巴比伦转结埃及，巴比伦王尼布甲尼撒亲率大军合围耶路撒冷。期间巴比伦军击退埃及援军，久围绝粮后于前五八七年夏攻破北墙，擒获外逃的西底家，焚毁圣殿王宫，掳其民入巴比伦，犹大亡国。注：任务表敌方标为以色列，实为犹大王国；破城年份另有前五八六年说。","sources":"列王纪下·第二十五章；耶利米书；巴比伦编年史"},
    "jialedi_nibujianisa@-605": {"strategic":["公元前六〇五年，亚述都城虽倾，近东霸权仍未底定。埃及法老尼科二世借扶助亚述残部之名北上，重兵扼守幼发拉底河西岸要塞卡基米什，阻遏新巴比伦西进。年迈的巴比伦王留镇都城，将全国主力交付王储尼布甲尼撒；尼布甲尼撒溯河北上直抵卡基米什对岸。"],"tactical":["卡基米什紧扼幼发拉底河上游渡口，尼科二世集埃及精兵与雇佣步卒重防浅滩。尼布甲尼撒避开正面强渡，密率主力自下游悄然济河，迂回城西截断埃军后路。尼科二世仓促出战，两军自旷野鏖战至街巷火海，埃军防线全面崩盘；尼科二世败逃南归，叙利亚与迦南尽归新巴比伦号令。"],"history":"公元前六〇五年夏，埃及法老尼科二世占据幼发拉底河上游重镇卡基米什，联合亚述残余阻遏新巴比伦西进。巴比伦王储尼布甲尼撒统军北上，绕渡幼发拉底河奇袭卡基米什，内外夹击歼灭埃及主力，尼科二世败逃，新巴比伦尽收黎凡特霸权。定值：敌将取埃及法老尼科二世。","sources":"巴比伦编年史；耶利米书·第四十六章"},
    "jiaodong_tiandan": {"strategic":["公元前二七九年，距离燕军统帅乐毅攻破临淄、横扫齐境已历五载，堂堂东海强齐仅剩莒与即墨两座孤城尚存一线生机。即墨守大夫战死后，城中军民因齐宗室远支田单先前锯断车轴包铁脱险有智谋，共推田单守城御敌。面对乐毅筑垒缓攻、怀柔收心的老辣方略，田单苦苦支撑难寻破局之机；","恰在此时燕昭王病逝，新继位的燕惠王做太子时便与乐毅有隙。田单敏锐抓住这一天赐裂缝，密派细作潜入燕都散布谣言，声称乐毅久攻两城不下实欲留齐自立为王，齐人最怕燕国另换他将残虐攻城；","燕惠王果然中计，临阵撤换乐毅，改派刚愎轻敌的骑劫接掌围城大军，齐国绝地翻盘的良机终于到来。"],"tactical":["即墨城外燕军营寨连绵，新帅骑劫到任后尽改乐毅宽厚旧政，田单顺势步步设局激起全城死志；他先托言天降神师振奋人心，再故意散布怕燕军割降卒之鼻、掘城外祖坟的流言，骑劫果真照做，引得即墨军民痛哭切齿、皆欲出城死战。","田单见士气可用，便命城中富户献金贿赂燕将诈称即将开城投降，将老弱女子列于城头，令骑劫全军彻底放松戒备。入夜之后，田单将城内搜集来的耕牛身披五彩龙纹布帛，牛角绑紧锋利尖刀，牛尾系上浸满油脂的芦苇，预先在城墙底部凿开多处暗穴；","半夜时分牛尾火起，受痛狂怒的火牛群冲出墙洞直扑漆黑的燕军大营，涂抹彩纹的齐国死士紧随其后挥刀猛砍，城上老弱敲击铜器震天动地。燕军在睡梦中以为神兵天降，魂飞魄散自相践踏，骑劫死于乱军之中，田单乘胜席卷东进，尽复齐国故地。"],"history":"公元前二八四年乐毅破齐后，齐宗室田单率族人以铁笼车轴脱走东保即墨，被城民推为主将死守五载。公元前二七九年燕昭王死、燕惠王立，田单纵反间计使燕惠王以躁进的骑劫取代乐毅，复设神师与诈降麻痹燕军；趁夜搜集城中耕牛缚刃于角、系油苇于尾点燃冲阵，壮士绘五彩随牛掩杀，大破燕军并阵斩骑劫，一举收复齐国失地复立齐襄王。","sources":"史记·田单列传；战国策·齐策六"},
    "jin_xianzhen": {"strategic":["公元前六三二年，中原霸主虚位，楚国大举北进，楚令尹子玉统兵围困宋都。晋中军元帅先轸献策，攻破附楚的曹卫两国并激齐秦参战，迫使子玉释宋北上寻战。先轸统晋军主动退避三舍以报旧惠、骄敌致师，将孤军深入的子玉主力引至卫地城濮。"],"tactical":["卫地城濮原野与丘陵相间，外有泽薮阻隔，两军列阵对决。晋下军给战马蒙虎皮直冲楚右翼陈蔡军，敌马惊溃，楚右翼先行瓦解；晋上军竖双旆佯退，诱楚左翼脱离本阵急追。先轸看准战机，率中军精锐拦腰横击，配合上军回身夹攻大破楚师；子玉败归自尽，晋国由此奠定中原霸业。"],"history":"公元前六三二年四月，晋文公以先轸为中军元帅南下救宋，攻曹伐卫致楚师，与楚令尹子玉决战于卫地城濮。晋军退避三舍骄敌，决战时下军蒙虎皮冲溃陈蔡右军，上军设二旆佯退诱敌，先轸率中军横击大破楚左军，子玉败归自尽，晋国践土会盟确立中原霸主地位。","sources":"左传·僖公二十八年；史记·晋世家"},
    "jin_xianzhen@-627": {"strategic":["公元前六二七年，晋文公新丧，秦穆公不听蹇叔苦谏，遣孟明视统兵越晋南远袭郑国。因郑商弦高沿途示警，孟明视见郑有备，袭灭滑国后引军西归。晋中军元帅先轸力斥纵敌之议，说动晋襄公染黑丧服出征，联姜戎星夜赶赴秦军必经的殽山设伏。"],"tactical":["殽山分南北两险峰，谷深林密、栈道狭长，车马穿行进退维谷。孟明视率疲敝秦军入谷，轻视晋丧而未派斥候搜山，队列拉成一线。待秦军尽入袋形谷底，先轸令两侧绝壁伏兵礌石齐下，封死东西谷口断其退路，居高临下四面掩杀。秦军全军覆没，孟明视被擒，秦国东进争霸之路自此锁死。"],"history":"公元前六二七年春，秦穆公违蹇叔之谏，遣孟明视等率军越晋境远袭郑国；因郑商弦高犒师示警，秦军灭滑而还。时晋文公新丧，中军元帅先轸力劝晋襄公墨绖从戎，联姜戎设伏于殽山峡谷，全歼秦军并生擒孟明视等三帅，锁死秦国东进中原之路。定值：敌将取秦军主帅孟明视。","sources":"左传·僖公三十三年；史记·晋世家；史记·秦本纪"},
    "kongque_zhantuoluo": {"strategic":["公元前四世纪末，恒河中下游的摩揭陀王国在难陀王朝统辖下坐拥广袤沃土与庞大战象车步大军，然而末代君主达那难陀贪鄙残暴、横征暴敛，不仅贵族武士离心，连婆罗门学者亦深受羞辱。","与此同时，西北印度河流域因马其顿东征军撤离陷入权力真空，青年豪杰旃陀罗笈多在导师考底利耶指点下揭竿而起；他吸取早年贸然直袭摩揭陀受挫的教训，先在旁遮普收编山林劲旅与西北诸部，驱逐异族总督建成稳固根据地。","公元前三二一年，羽翼丰满的旃陀罗笈多统率西北精兵沿恒河走廊大举东进，节节剪除难陀边防重镇，兵锋直逼摩揭陀富丽宏伟的都城华氏城。"],"tactical":["华氏城坐落于恒河与宋河交汇要冲，外有宽阔护城深壕与连绵高耸的巨木城垣、箭楼拱卫，达那难陀聚集难陀王朝残存的战象与重兵据守都城，妄图凭天险顽抗。","旃陀罗笈多与考底利耶采取内外并举之策，一面在城外水陆要道严密布防，以精锐骑射与山地劲卒击败难陀出城迎战的部队，断绝华氏城四方税赋粮船；一面利用达那难陀失道寡助的困局，暗中分化瓦解城内重臣与守军斗志。","待围城条件成熟，旃陀罗笈多挥动大军冒着矢石强渡深壕、猛攻城门防线，一举攻破华氏城；达那难陀兵败倒台，难陀王朝就此覆灭。旃陀罗笈多于华氏城正式登基创立孔雀帝国，开创了北印度大一统的恢宏时代。"],"history":"约公元前三二一年，出身卑微的印度青年统帅旃陀罗笈多在智者考底利耶即遮那迦辅佐下，先扫清亚历山大东征撤离后的西北印度旁遮普诸驻军，积蓄实力后挥师东向恒河流域，进攻统治摩揭陀的难陀王朝末王达那难陀。经外围扫荡后合围攻克摩揭陀都城华氏城，推翻难陀王朝，开创印度历史上首个统一大帝国孔雀王朝。定值：年份统一取前三二一年。","sources":"往世书；大史；政事论；查士丁·腓力史概要"},
    "kongque_zhantuoluo@-305": {"strategic":["公元前四世纪末，西方亚历山大继业者之中的枭雄塞琉古稳固两河与波斯高原统治后，意欲效仿先王东征伟业，重夺印度河流域诸旧省。然而此时的印度早已今非昔比，往昔四分五裂的西北诸邦均已被推翻难陀王朝的孔雀大帝旃陀罗笈多熔铸为一统强国，国力如日中天。","公元前三〇五年，塞琉古统率久历西亚战火的马其顿式方阵与东方骑兵强渡印度河东进；旃陀罗笈多闻警毫无退让，亲统孔雀帝国遮天蔽日的战象军团、战车与重步劲旅西出迎敌，东西方两大新兴帝国在印度河谷迎头相撞。"],"tactical":["印度河谷平畴与丘陵交接，湿热河滩与湍急支流令远道而来的塞琉古重装长矛方阵倍感掣肘。吸取了往昔波鲁斯单薄兵力败于河岸的教训，旃陀罗笈多坐拥举国供养的庞大战象群与严密车步弓骑协同体系，进退调度章法森严。","交锋展开后，塞琉古虽凭老练方阵与骑队奋力冲击，但在孔雀大军层出不穷的披甲巨象与密集竹弓长箭压制下处处受阻，西方战马畏象不前，后勤粮道更随时面临截断之危。连番较量下来塞琉古深知绝无力撼动根基深厚的孔雀帝国，而西方安提柯的决战威胁又迫在眉睫，遂主动遣使议和。","旃陀罗笈多展现大国胸怀，与塞琉古缔结王室姻亲盟约，一举将兴都库什山以南的犍陀罗、格德罗西亚与阿拉霍西亚广袤疆土收入孔雀版图，并慨赠大批战象助塞琉古西归决战，孔雀帝国疆域由此推向极盛。"],"history":"公元前三〇五年至前三〇三年间，已据有巴比伦与伊朗高原的塞琉古帝国开创者塞琉古东征，渡过印度河企图收回亚历山大昔日征服的西北印度诸行省，迎头遇上已完成北印度大一统的孔雀帝国皇帝旃陀罗笈多。旃陀罗笈多凭借绝对优势的本土战象与重兵挫败塞琉古东进企图，迫使塞琉古缔结和约与联姻，割让犍陀罗、阿拉霍西亚等大片西境，孔雀回赠战象。","sources":"斯特拉波·地理志·第十五卷；阿庇安·叙利亚战记；普鲁塔克·亚历山大传"},
    "liguo_zhaoshe": {"strategic":["公元前二六九年，秦国在连挫韩魏楚诸邦之后，首次将扩张矛头指向胡服骑射后崛起的北方强邻赵国，秦王命猛将胡阳统率大军越过韩国上党山地，突然合围太行西麓重镇阏与。","赵惠文王紧急召见宿将廉颇与乐乘商议救援，两位老将审度山川地势，一致认为前往阏与山路遥远且羊肠险窄，大军难以展开，主张放弃救援。满朝束手之际，曾执掌赋税执法不阿的赵奢挺身进言，指出正因山道遥远狭窄，恰如两鼠相斗于深穴之内，全凭主将胆魄勇决争胜。","赵惠文王大为振奋，当即拜赵奢为将，统率赵国劲旅西出邯郸奔赴太行险境。"],"tactical":["阏与深处太行崇山环抱之中，城北一处险峻高岭俯瞰全城内外，实乃控扼战局的咽喉制高点。赵奢率军刚离邯郸不远，便反常下令就地筑起坚固营垒，严禁军中任何人妄言军事，违者立斩；","当胡阳分兵进逼武安试探虚实时，一名赵军军候开口请救武安，赵奢当场将其斩首示众，继续高挂免战牌驻守二十八日，更厚待抓获的秦军细作放归报信。胡阳闻报抚掌大笑，彻底认定赵奢贪生惜城、绝不敢西进救阏与，遂放松外围警戒专心攻城。","岂料秦探刚走，赵奢即刻下令全军卸去沉重铠甲辎重，昼夜疾奔赶赴前线，抢在秦军反应之前登顶阏与北山，依军士许历进言构筑壁垒列开厚阵。胡阳大惊，急发秦师蜂拥仰攻北山；","赵奢占尽地利居高临下迎头痛击，与阏与城内守军内外夹攻，杀得秦军尸横山谷，胡阳狼狈解围败逃，赵奢一战威震列国。"],"history":"公元前二六九年，秦昭襄王遣大将胡阳即胡伤越韩境围攻赵地阏与。赵惠文王召廉颇、乐乘问计，二人皆以道远险狭难救为对；唯田部吏出身的赵奢慨然献言道远险狭犹如两鼠斗于穴中，将勇者胜。赵奢挂帅出邯郸三十里即筑垒坚壁二十八日麻痹秦军，诛杀妄议进兵者，随即卷甲疾趋两日一夜抢占阏与北山高地，居高俯冲大破胡阳秦军，受封马服君。定值：年份取前二六九年。","sources":"史记·廉颇蔺相如列传；战国策·赵策三"},
    "maqidun_craterus": {"strategic":["公元前三二三年夏，征服东方的亚历山大骤逝于巴比伦，消息传回希腊本土，久受压制的雅典群情激昂；雅典立即串联埃托利亚与色萨利各邦掀起反马其顿起义，推举安提菲卢斯统兵北上，将欧洲摄政安提帕特围困在拉米亚孤城之中。","危急关头，素受全军将士敬仰、正奉先王遗命率领宿战退伍老兵自奇里乞亚返乡的马其顿名将克拉特罗斯毅然扛起重任，加速率领久经东方大战锤炼的老兵军团横渡赫勒斯滂海峡驰援欧洲。","克拉特罗斯与脱困的安提帕特顺遂合兵，主动把全军最高号令权让予年长的安提帕特，两部精锐南下压入色萨利克兰农平原，迎战安提菲卢斯统率的希腊联军。"],"tactical":["克兰农平原地势开阔起伏，南侧倚靠绵延高丘。雅典统帅安提菲卢斯自知麾下各邦公民步卒难敌马其顿宿战老兵，把全部胜算押在盟友精锐的色萨利骑队身上，企图重演先前骑战击杀马其顿援帅之功。交战打响后，色萨利骑队果然在平原上压制了马其顿骑兵；","克拉特罗斯与安提帕特见状毫不慌乱，果断令整肃厚重的马其顿萨里沙长矛方阵全线推进，迎面猛碾安提菲卢斯布在平地上的希腊重装步阵。在无坚不摧的老兵长矛冲击下，希腊步卒防线节节败退，被迫逃上后方崎岖山丘自保；正占上风的色萨利骑队见己方步阵溃败，只得放弃追击回护山脚。","次日安提菲卢斯见各邦援兵迟迟不至而克拉特罗斯大军阵势森严，被迫遣使求和；克拉特罗斯与安提帕特坚持与各邦逐一单独议和，一举拆散希腊同盟，进驻雅典废除民主政体，彻底稳固了马其顿在欧洲的统治。"],"history":"公元前三二三年亚历山大病逝巴比伦，雅典联合埃托利亚、色萨利诸邦发动拉米亚战争反抗马其顿统治，将欧洲摄政安提帕特围困于拉米亚城。正率退伍老兵西归的马其顿名将克拉特罗斯火速渡海驰援，于公元前三二二年八月会合安提帕特，在色萨利克兰农平原以优势重装方阵击退雅典将领安提菲卢斯步阵，迫使希腊同盟瓦解投降，雅典民主制随之终结。","sources":"西西里的狄奥多罗斯·历史丛书·第十八卷；普鲁塔克·福基翁传"},
    "maqidun_craterus@-326": {"strategic":["公元前三二六年春，马其顿远征军翻越兴都库什山脉踏入印度河流域，塔克西拉国王主动迎降；唯独海达斯佩斯河以东波罗婆王国的雄主波鲁斯拒绝臣服，集结精悍步骑与庞大战象群陈兵东岸。","时值南亚雨季来临，冰川融水与连绵暴雨令海达斯佩斯河暴涨湍急，战马一旦临近对岸象群便会受惊坠水，正面强渡无异自寻死路。","老练沉稳的大将克拉特罗斯受命执掌西岸主营重兵，连日与对岸波鲁斯主力隔河相持、昼夜佯动喧嚣，一面死死吸住波鲁斯的目光，一面掩护亚历山大率突击分队在风雨黑夜中悄然向上游密林迂回。"],"tactical":["海达斯佩斯河宽水急，东岸泥泞湿滑，波鲁斯将高大如城垛的战象一字排在河滩正对克拉特罗斯大营之处。按照事先严密约定，只要波鲁斯留有战象守卫渡口，克拉特罗斯便只作渡河假象按兵不动；一旦侦知波鲁斯把全部战象调走迎击上游，便立即全军抢渡。","暴雨破晓之后，上游传来偷渡成功的讯息，波鲁斯急忙仅留少许偏师守滩，亲统全部战象与主力北上同亚历山大展开惨烈血战。","西岸高处的克拉特罗斯见对岸巨象尽数北移，当即一声令下，督率养精蓄锐的巴克特里亚骑队与马其顿重装步阵乘船驾筏强行横渡激流，一鼓作气冲垮滩头守敌，随即整队杀向主战场背后。","此时正面印军正与马其顿军苦斗力竭，忽见克拉特罗斯生力大军自后方席卷而来，阵线彻底崩溃，身负重伤的波鲁斯力战被俘，旁遮普大地自此臣服于马其顿兵威之下。"],"history":"公元前三二六年五月，马其顿东征军进抵旁遮普海达斯佩斯河即杰赫勒姆河西岸，波罗婆国王波鲁斯率大批战象、战车与步骑严守东岸渡口。亚历山大命心腹大将克拉特罗斯统率大营主力留守正面渡口张扬旗鼓，牵制波鲁斯视线，自率精锐乘暴雨夜自上游偷渡。待波鲁斯倾军北上迎战亚历山大之际，克拉特罗斯把握战机率生力军强渡大河自背后痛击印军，铸就完胜。","sources":"阿里安·亚历山大远征记·第五卷；普鲁塔克·亚历山大传"},
    "mi_chu_xionglv": {"strategic":["公元前五九七年，晋楚围绕中原枢纽郑国激烈争锋，楚庄王熊旅亲统楚师围迫郑国降楚。晋中军元帅荀林父救郑行至黄河，闻郑已服楚本欲引还，副帅先縠却违命擅渡黄河，迫使晋军全师南渡屯于邲地。熊旅侦知晋军将帅失和、进退狐疑，当即挥师北上进逼郑郊邲地。"],"tactical":["郑郊邲地北靠黄河，荀林父背水扎营，诸将战和不一、戒备松懈。恰逢晋将擅赴楚营挑衅，晋营发车接应扬起漫天尘土；熊旅登车望见晋营纷乱，断定其号令分裂，立挥楚军分路突击。晋军未及成列便遭楚车骑席卷，荀林父慌令抢渡黄河，溃兵争舟自相斫指；熊旅饮马黄河，一战确立楚国中原霸业。"],"history":"公元前五九七年夏，楚庄王熊旅围郑迫其降楚，晋中军元帅荀林父救郑迟至黄河欲还，中军佐先縠违命独渡，晋军被迫全军南渡屯于郑郊邲地。和谈之际晋将挑衅破局，熊旅乘晋军将帅失和、未及成列发动突袭，晋军大溃争舟渡河，楚国一战夺得中原霸权。","sources":"左传·宣公十二年；史记·楚世家"},
    "pajiama_oumainisi": {"strategic":["公元前二六二年，小亚细亚西北部的山城帕加马迎来决定生死存亡的严峻考验。早年菲莱泰罗斯借继业者混战之机掌管帕加马巨额宝库，在名义臣服塞琉古帝国的同时暗中招兵买马、结好邻邦；","及至其侄欧迈尼斯继掌大权，帕加马正式谋求摆脱塞琉古宗主羁绊，更与塞琉古的宿敌埃及托勒密王朝暗通声气。刚刚处死叛乱长子、急于重振帝国西疆威权的塞琉古国王安条克一世决不容许附庸独立，亲统塞琉古大军推进至吕底亚核心重镇萨第斯，准备一举荡平帕加马。","年轻果敢的欧迈尼斯拒绝坐困孤城待毙，以帕加马丰厚财力重赏麾下常备雇佣精兵，主动挥师南下迎向萨第斯城下。"],"tactical":["萨第斯城外赫尔姆斯河谷平原与丘陵相接，安条克一世依仗塞琉古帝国广土众民的兵力优势在城郊展开庞大战阵，企图以正面重装方阵压垮弱小的帕加马军队。然而塞琉古大军长年疲于高卢部族侵扰与叙利亚战事，内部宫廷动荡刚过，将士锐气远不及往昔；","反观欧迈尼斯麾下的希腊与色雷斯雇佣劲旅粮饷丰足、久经操演，指挥灵动如臂使指。交锋之中，欧迈尼斯巧妙依托萨第斯外围起伏地形避开塞琉古方阵正面锋芒，集中精锐骑队与轻盾步卒高速迂回，猛烈冲击安条克一世大军暴露的侧翼与接合部。","塞琉古军阵调度迟缓，侧翼一溃顿时牵动全阵哗乱，大军在萨第斯城下惨败收场；安条克一世退返后不久郁辞病逝，欧迈尼斯则凯旋归国，将帕加马疆域大幅推向爱琴海沿岸，正式屹立为独立强邦。"],"history":"公元前二六三年帕加马自立基础奠定者菲莱泰罗斯去世，侄子欧迈尼斯继位。一意恢复小亚细亚宗主权的塞琉古帝国国王安条克一世不甘帕加马脱离控制，于公元前二六二年亲统帝国大军进逼吕底亚首府萨第斯一带讨伐。欧迈尼斯不待敌军压境围城，主动率精悍雇佣军南下，在萨第斯城下野战中击败安条克一世主力，确立帕加马独立王国地位。","sources":"斯特拉波·地理志·第十三卷；阿庇安·叙利亚战记"},
    "qi_tianji": {"strategic":["公元前三四二年，魏国倾师猛攻弱韩以图独霸中原，齐王深知唇亡齿寒，复拜功臣田忌挂帅出征。田忌统齐国精锐西出临淄，避开韩境攻坚，轻装疾插魏国要害大梁；魏帅庞涓被迫放弃攻韩战果火速回师，田忌遂按方略引军移向齐魏边境马陵道。"],"tactical":["马陵道山路蜿蜒、谷深林幽，乃天然伏兵绝地。田忌严整约束齐军东撤，沿途逐日减灶示弱，诱轻敌冒进的庞涓撇下步阵孤军追入隘口。田忌早已督齐军主力在谷道尽头与两侧高坡伐木断路、张弩待敌；当夜庞涓入伏举火看字，田忌令四周伏弩齐鸣，步骑掩杀全歼敌前锋，庞涓自刎，田忌乘胜俘魏太子，齐国雄踞东方。"],"history":"公元前三四二年，魏国攻韩，齐威王拜田忌为主帅、孙膑为军师直趋大梁救韩。田忌配合减灶诱敌之策严整东撤，将魏帅庞涓诱入马陵道伏击全歼，乘胜再破魏后续大军并俘魏太子申，摧毁魏国霸业。定值：同场三行统一取前三四二年、战场马陵道。","sources":"史记·田敬仲完世家；史记·孙子吴起列传"},
    "qi_tianji@-353": {"strategic":["公元前三五三年，魏国四面征伐，大将庞涓久围赵都邯郸，齐国西境亦受威胁。齐王拜宗室名将田忌挂帅救赵；田忌从善如流，采纳军师避实击虚奇谋，舍赵境而挥师直插魏国腹心大梁。前线庞涓惊闻老巢告急，果撤赵围南返，田忌遂统齐师提前移屯桂陵待敌。"],"tactical":["桂陵横锁南北驿路，林丘起伏，极利阻击运动之敌。田忌将战车重步布于大道高地，分遣劲卒潜伏两翼沟林，严令全军寂然待命。未几庞涓督奔波疲惫的魏师赶抵，行军队列散乱脱节；田忌看准敌军喘息未定，亲擂战鼓挥中坚猛压、两翼合围，一举冲垮魏武卒并活捉庞涓，奠定齐魏平分秋色之势。"],"history":"公元前三五三年，齐宗室名将田忌挂帅救赵，虚心采纳门客军师孙膑围魏救赵之计，挥师西击魏国腹地诱魏帅庞涓回师。田忌统齐军主力抢占桂陵设伏截击，击溃疲敝魏军并生擒庞涓，扭转魏国独霸中原之局。定值：同场三行年份统一取前三五三年。","sources":"史记·田敬仲完世家；史记·孙子吴起列传"},
    "qin_hengyi": {"strategic":["公元前二三三年，秦王嬴政亲政后加快并吞六国步伐，头号劲敌仍是北方尚存精兵的赵国。前一年秦国猛将桓齮刚刚在平阳之战中斩杀赵帅扈辄，重创赵国南线主力，威震河北。","乘着破竹之势，桓齮并未循漳水正面旧路硬啃邯郸坚城，而是率领得胜秦师自上党秘密翻越太行山险道，大迂回插向邯郸东北腹地，接连拔取赤丽、进逼宜安，企图从侧背一举勒断赵都命脉。","邯郸朝野大震，赵王迁火速从北方抗匈前线召回名将李牧拜为大将军，统合全国精锐赶赴宜安与肥下一线迎堵桓齮。"],"tactical":["肥下与宜安毗邻滹沱河原野，背靠太行东麓丘陵，地形开阔中暗藏沟壑。桓齮挟平阳大胜余威屡次陈兵赵垒之前挑战，急欲与赵军主力速战决胜；不料新到的赵帅李牧一反扈辄浪战之失，严令赵军高垒深沟、终日椎牛飨士而严禁部众出战。","桓齮连日强攻赵壁无果，暗忖李牧必定畏惧秦军锐气不敢野战，遂生骄怠之心，亲率主力脱离宜安大本营东向猛攻肥下城邑，意图以攻城逼诱赵军分救。","岂料这正中李牧下怀，趁桓齮大营留守兵单、主力前出攻肥之际，李牧突然尽出精锐奇袭攻占秦军后方留守大营，尽夺其辎重，随即张开厚重两翼在肥下原野布成铁钳口袋。桓齮惊闻老营失守，急忙回师救援，迎头撞入李牧预设的两翼包抄网中；","秦军阵脚大乱全线崩溃，桓齮拼死杀开血路仅以身免，秦军灭赵攻势由此严重受挫。"],"history":"公元前二三四年秦大将桓齮在平阳大破赵军、斩赵帅扈辄。次年即公元前二三三年，桓齮乘胜东出上党越太行山再攻赵国，进围赤丽与宜安，直逼邯郸北翼。赵王迁急调雁门名将李牧拜大将军南下御秦；李牧在宜安、肥下筑垒坚守不出麻痹秦军，桓齮久攻不下遂分兵攻取肥下，营寨空虚之际遭李牧两翼钳形奇袭攻破大营，秦军惨败，桓齮仅率少量亲随突围逃归。","sources":"史记·廉颇蔺相如列传；史记·秦始皇本纪；战国策·赵策"},
    "qin_hengyi@-234": {"strategic":["公元前二三四年，秦王嬴政亲政剪除吕不韦与嫪毐集团后，正式掀起横扫山东六国的统一狂飙。此际北方劲敌赵国恰逢国丧动荡，赵悼襄王病逝，年幼昏聩的赵王迁嗣位，朝政大权落入奸佞宠臣郭开之手，昔日宿将廉颇流亡在外，名将李牧远戍代雁门防备匈奴，南线邯郸门户竟无良将坐镇。","秦大将桓齮奉命统率秦国虎狼之师借魏邺跳板北进，锋芒直刺漳水沿岸的赵南重镇平阳与武城；赵王迁惊慌失措，派亲近郭开的将领扈辄统兵南下迎堵，秦赵主力遂在平阳原野正面对撞。"],"tactical":["平阳地处邯郸以南、漳水北畔的开阔冲积平原，无险山峻岭可资依托，最利强军硬碰硬展开车骑步协同决战。赵帅扈辄虽通文墨却缺乏统御大军团野战的韬略，面对锐气正盛的桓齮秦师，既未凭漳水河防稳扎营垒挫敌锋芒，又贸然驱使赵军在平阳城外旷野与秦军主力正面对决。","桓齮看准赵军调度呆板、侧翼薄弱，亲自擂鼓催动秦国铁骑与锐士猛冲扈辄中军帅旗，以凌厉无匹的正面冲击配合两翼迂回包抄，瞬间撕裂赵军防线。赵军阵脚大乱、首尾不能相救，在平阳原野陷入秦军四面围杀之中，主帅扈辄突围不得当场战死沙场，赵国南线野战精锐损失惨重；","桓齮一战踏平平阳与武城，打得邯郸门户洞开，逼得赵廷不得不从北边召回李牧救亡。"],"history":"公元前二三四年，秦王嬴政乘赵悼襄王新丧、少主赵王迁初立且廉颇庞煖皆不在朝之机，命大将桓齮率秦军主力大举攻赵，渡漳水进拔平阳与武城。赵王迁派宠臣郭开举荐的将领扈辄率军南下救援，桓齮在平阳城外野战中正面击溃赵军主力，阵斩赵帅扈辄，重创赵国南线门户。","sources":"史记·秦始皇本纪；史记·赵世家；资治通鉴"},
    "qin_simacuo": {"strategic":["公元前三一六年，西方强秦正值商鞅变法之后锐意扩张之际，南方秦岭背后的古蜀与巴国突发内讧；蜀王芦子霸王与封于葭萌的胞弟苴侯交恶，兴兵伐苴，苴侯奔巴，巴蜀双方竟同时派使者翻越秦岭向秦惠文王告急求援。","秦廷之上爆发著名战略论战，相国张仪主张发兵东伐韩国、进逼周室以挟天子令天下；大将司马错则深刻指出攻韩劫天子必招山东诸侯合纵攻秦之恶名，不如借平乱之名南取物产丰饶、政乱无备的巴蜀，既得广土众民以富国，又可顺江东下拊楚国之背。","秦惠文王拍板采纳司马错远略，当即命司马错与张仪统率秦师踏上险峻难行的金牛石牛栈道，翻山南指蜀国北门重关葭萌关。"],"tactical":["葭萌关雄踞白龙江与嘉陵江交汇山地，崇山夹峙、栈道高悬，实为拱卫成都平原的咽喉锁钥，古蜀王芦子霸王闻秦军假道南下，急忙亲统蜀军主力北上赶至葭萌关据险迎击。然而古蜀长年偏安盆地，兵器甲胄与战阵调度皆远逊于在关中与三晋血火搏杀出来的秦国锐士。","司马错率秦军出栈道后毫不迁延，趁蜀军人心浮动、盟友苴巴倒戈接应之机，集中强弩与锐卒猛攻葭萌关防线，在山地野战与关隘攻坚中连战连捷，一举击溃蜀王主力夺下雄关。芦子霸王仓皇南逃至武阳一带，遭司马错追兵赶上击杀，蜀相与太子亦在逢乡败亡；","司马错乘胜顺势兼并巴国，将天府沃野尽数纳入秦国版图，为日后秦并六国筑起了永不枯竭的粮仓根基。"],"history":"公元前三一六年，古蜀王开明氏即芦子霸王与封于汉中葭萌的弟弟苴侯反目，苴侯联巴国相攻，蜀巴苴皆遣使向秦惠文王求救。秦廷御前廷议，张仪主伐韩挟天子，司马错力主先取富庶广袤的巴蜀以资国力、占对楚上游。秦惠文王纳司马错策，遣司马错、张仪、都尉墨自石牛道南下攻破葭萌关，击杀蜀王，一举灭蜀兼巴。定值：敌方国号改挂新增势力古蜀。","sources":"战国策·秦策一；史记·张仪列传；华阳国志·蜀志"},
    "qin_simacuo@-280": {"strategic":["公元前二八〇年，距离司马错率师灭蜀已历三十余载，经过秦国两代经营，巴蜀盆地早已化作甲兵强盛、积粟如山的战略大后方。此时楚顷襄王治下的楚国虽在淮汉北线重兵防范秦国武关与南阳通道，西南腹背的武陵黔中山地却自恃山高水险而防备空虚。","秦昭襄王决意兑现当年司马错得蜀则得楚的宏伟蓝图，特诏白发老帅司马错再度披挂出征；司马错先调陇西劲卒南入蜀郡，会合巴蜀精兵，打造高大楼船装载充足军粮，避开长江三峡正面险滩，自巴涪水南插武陵水道，神不知鬼不觉直扑楚国西南重藩黔中。"],"tactical":["黔中群峰叠嶂，酉水与沅水穿行于深山峡谷之间，楚顷襄王在西南边郡仅置常规戍卒把守水陆关隘，做梦也未料到秦军竟能携大船重兵翻越崇山自上游顺流天降。司马错统率巴蜀水陆劲旅乘湍急水势浩荡东下，战船顺流疾航，兵锋所至犹如高屋建瓴。","楚国黔中守军仓促依托沿江山寨与渡口节节阻击，司马错命水师楼船正面抢滩夺渡，同时遣惯走山林的巴蜀锐士攀越崖壁绕袭敌砦后背，水陆夹击连破楚军沿江防线，一举攻拔黔中全郡。","西南门户骤失令郢都侧翼完全暴露在秦军兵锋之下，楚顷襄王惊恐震动，不得不急忙遣使入秦卑辞请和，忍痛献出汉水以北及上庸大片要害国土；司马错老当益壮一战功成，直接为两年后白起攻破郢都铺平了道路。"],"history":"公元前二八〇年，秦昭襄王决意实施大举灭楚战略，启用三十余年前灭蜀开疆的元勋老将司马错，发陇西军入蜀，征发巴蜀士卒与大批战船粮粟，自涪水、乌江越武陵山脉顺沅水奇袭楚国西南屏障黔中郡。楚顷襄王猝不及防，黔中防线崩溃失守，被迫割让汉水以北及上庸之地向秦求和，完美兑现了司马错早年得蜀即得楚的战略预言。","sources":"史记·秦本纪；史记·楚世家；华阳国志·蜀志"},
    "shang_weiwuji": {"strategic":["公元前二五七年，长平惨败后的赵国面临亡国灭种之祸，秦大将王龁统领重兵将赵都邯郸围困逾年，城中粮尽柴绝、军民析骨而炊，平原君夫人即魏无忌胞姐日夜派使者向魏国哭求救兵。","魏安釐王起初派将军晋鄙领兵北援，一闻秦王严词恫吓诸侯敢救赵者移师先击之，便吓得急令晋鄙驻扎汤阴邺城按兵不动。素以礼贤下士闻名的信陵君魏无忌苦谏魏王不听，决意拼死独赴邯郸与赵共存亡；","临行之际隐士侯嬴献出窃符救赵奇策，由曾受魏无忌报父仇大恩的王宠姬如姬趁夜潜入魏王寝宫盗出兵符。魏无忌怀揣虎符与大力士朱亥疾驰赶赴邺城军营，一场扭转六国危局的壮举就此上演。"],"tactical":["邯郸城外秦军连营环列，王龁督率秦师昼夜猛攻，赵都旦夕将破。魏无忌赶抵邺营出示虎符矫诏接管兵权，老将晋鄙起疑要求再行奏请核实，随行力士朱亥当即自袖中抽出沉重铁椎击毙晋鄙；","魏无忌夺掌帅印后颁下严明宽仁之令，凡父子同在军中者父归，兄弟同在军中者兄归，独子无兄弟者归养父母，去弱留强整编出一支人人愿为公子效死的精悍劲旅，星夜挥师北进。","恰在此时楚国春申君与景阳所率援军亦自南赶到，魏无忌指挥魏军精锐顶着秦军锋芒，自西侧悍然猛扑王龁围城本阵，城内平原君亦率敢死之士大开城门杀出夹击。久围疲敝的秦军腹背受创、大败溃散，王龁仅率残部狼狈西逃，被围困的秦副将郑安平则向赵军缴械投降；","邯郸之围一朝得解，魏无忌威震天下，硬生生为山东六国续命三十余载。"],"history":"公元前二五九年至前二五七年，长平战后秦军乘胜围攻赵都邯郸，王陵失利后秦改派王龁主攻，邯郸危在旦夕。魏安釐王派晋鄙领兵救赵，因惧秦恐吓停驻邺城观望。魏信陵君魏无忌采纳侯嬴秘计，请如姬自魏王卧内盗出虎符，赴邺营令朱亥以铁椎击杀疑虑不从的晋鄙，精选锐卒北上，会合楚景阳援军与城内平原君里应外合，于邯郸城下大破王龁秦军。","sources":"史记·魏公子列传；史记·赵世家；战国策"},
    "shang_weiwuji@-247": {"strategic":["公元前二四七年，当年窃符救赵后留居邯郸十载的信陵君魏无忌再度被推上挽救中原危局的风口浪尖。秦国自恢复元气后，由老练大将蒙骜挂帅连年东进蚕食韩赵魏三国，置三川与太原郡，今岁更大举攻魏，连拔高都与汲城，兵锋直逼魏国都城大梁，魏军屡战屡败无人能挡。","焦头烂额的魏安釐王只得尽弃前嫌，连派快马捧着上将军印信前往赵国苦请胞弟归国主兵；魏无忌受毛公与薛公劝诫幡然醒悟魏亡则一己安能独存，遂洒泪辞赵归魏。","魏无忌复出挂帅的消息传遍山东，赵、韩、楚、燕各国感念其威德义举纷纷倾发精兵来会，魏无忌并统五国合纵大军浩荡西进，迎击蒙骜统率的秦国主力于河外原野。"],"tactical":["河外位于黄河大拐弯以南、洛阳至函谷关之间的战略走廊，背水临山，乃是秦军东出三晋的咽喉通道。蒙骜统领惯打顺风仗的秦国劲旅在此严阵设防，企图阻遏山东联军西进。往昔诸侯合纵往往各怀鬼胎、号令不一，此番在名满天下的魏无忌亲自统御调度之下，五国将士却如臂使指、同仇敌忾。","交战打响后，魏无忌身先士卒督率魏武卒居中强压秦阵，燕赵铁骑与韩楚劲弓分自两翼凶猛包抄突击，一举冲垮蒙骜精心构筑的河外防线。秦军遭遇罕见重创，全线崩溃西逃；魏无忌毫不留情挥动五国联军衔尾疾追，一路收复失地直抵秦国国门天险函谷关下，日夜猛叩关门仰攻。","蒙骜残军吓得缩入函谷关内紧闭城门，任凭关外诸侯叫阵绝不敢再探出一步，魏无忌缔造了战国晚期合纵攻秦的最后辉煌巅峰。"],"history":"公元前二四七年，秦庄襄王命大将蒙骜连年东伐三晋，攻占韩赵魏大片城邑并进逼魏都大梁。魏安釐王多次遣使赴赵迎回客居十年的信陵君魏无忌拜为上将军；魏无忌致书各诸侯，赵、楚、韩、燕争相发兵，唯齐不至，魏无忌统率五国联军在黄河南岸的河外大破蒙骜秦军，一路追至函谷关下叩关攻秦，迫使秦军闭关不敢复出。","sources":"史记·魏公子列传；史记·秦本纪；资治通鉴"},
    "sumeier_nabopalasa": {"strategic":["公元前六一二年，曾称霸西亚的亚述帝国因连年内耗走向衰颓。新巴比伦国王那波帕拉萨在南方起兵逐走亚述驻军，并与东方米底王国缔盟夹击。亚述王伊什昆节节败退，收缩残部退保都城尼尼微；那波帕拉萨遂统巴比伦大军溯底格里斯河北上，与米底盟军合围尼尼微。"],"tactical":["尼尼微矗立底格里斯河东岸，双层巨垣高耸，科斯尔河穿城而过，伊什昆督残存禁卫闭门死守。那波帕拉萨与米底军合围猛攻累月，适逢雨季山洪暴涨冲软临水城基；联军趁势掘毁墙垣缺口，顺河床突入内城展开巷战。伊什昆于王宫自焚，尼尼微化为废墟，两河霸权自此转归新巴比伦。"],"history":"公元前六一二年夏，新巴比伦国王那波帕拉萨与米底国王基亚克萨雷斯会师底格里斯河东岸，合围亚述都城尼尼微。联军围攻三月，借雨季河水暴涨冲毁城垣缺口杀入内城，亚述王伊什昆自焚于王宫，尼尼微化为废墟，亚述帝国覆亡。注：任务表我方势力标为迦勒底，播报按当时国号称巴比伦或新巴比伦。","sources":"巴比伦尼尼微陷落编年史；希罗多德·历史"},
    "tuolemi_tuolemi": {"strategic":["公元前三二三年亚历山大驾崩之后，手握帝国帅印的摄政佩尔狄卡斯力图维持庞大帝国的集权统一，而受命出镇埃及的昔日近卫官托勒密一世却早已看透大一统难以为继，一心将富饶封闭的尼罗河流域经营成独立基业。","托勒密一世不仅处死佩尔狄卡斯安插的副手、吞并昔兰尼，更公然派兵在叙利亚半途截走运往马其顿安葬的亚历山大金棺，迎回埃及以聚拢全军威望，同时秘密联络安提帕特与克拉特罗斯结成反摄政同盟。","公元前三二一年，震怒的佩尔狄卡斯决定先平南方，挟持帝国名义共治双王，亲率王家方阵与战象浩荡穿越西奈沙碛，直抵托勒密一世严密设防的埃及东境门户佩鲁西姆。"],"tactical":["佩鲁西姆与尼罗河东支沿线河渠纵横，托勒密一世早已在各处浅滩渡口修筑坚固堡垒、密布拒马桩栅。佩尔狄卡斯初抵佩鲁西姆企图疏浚旧渠绕防，不料堤坝崩决毁坏军粮，部众已生怨言；他遂沿河上溯强攻托勒密一世驻守的骆驼堡要塞，驱赶战象在前撞拆栅栏、盾牌兵架梯登墙。","危急时刻托勒密一世亲自跃上墙垛，手持长矛刺瞎领头战象双目、击杀印度象夫，以无畏胆魄激起守军死战之心，血战竟日硬生生挡住了帝国王家精锐。佩尔狄卡斯不甘受挫，又乘夜移师孟菲斯附近浅滩强渡尼罗河，结果大批士卒踩空沙洲溺毙于湍流或丧生鳄吻，进退两难。","连番败绩加上佩尔狄卡斯平日刚愎严苛，终引发军中大哗，骑兵统领塞琉古等将领闯入帅帐刺杀佩尔狄卡斯；次日托勒密一世亲赴敌营厚赐粮秣抚慰将士，自此稳坐埃及王座，亚历山大帝国彻底走向分崩离析。"],"history":"公元前三二一年，亚历山大帝国摄政佩尔狄卡斯为惩罚埃及总督托勒密一世半途劫走亚历山大灵柩并私结同盟，挟两位傀儡国王亲统帝国主力南征埃及。佩尔狄卡斯进抵东门佩鲁西姆受阻后溯尼罗河强攻骆驼堡等渡口，托勒密一世身先士卒死守壁垒，河水冲散攻军并引来鳄鱼吞噬落水士卒，帝国军死伤惨重哗变，塞琉古等部将刺杀佩尔狄卡斯，托勒密自此稳据埃及。定值：年份统一取前三二一年。","sources":"西西里的狄奥多罗斯·历史丛书·第十八卷；阿里安·继业者史残篇"},
    "tuolemi_tuolemi@-312": {"strategic":["公元前四世纪末，独眼安提柯一世驱逐巴比伦总督塞琉古后独霸亚洲，并将年少英武的爱子德米特里一世留在巴勒斯坦重镇加沙驻防，时刻威胁埃及北门。逃亡投奔埃及的塞琉古力劝托勒密一世趁安提柯一世主力远在小亚细亚之际主动北上出击，夺取柯里叙利亚缓冲地带。","公元前三一二年春，托勒密一世与塞琉古携手统率埃及马其顿精兵、雇佣军与本土埃及步卒自亚历山大港启程，稳步穿越西奈荒漠直抵加沙城南；不听老将劝阻的年轻统帅德米特里一世执意列阵迎战，双方在加沙沿海沙原摆开了决战架势。"],"tactical":["加沙城外滨海平原坦阔，德米特里一世自恃麾下拥有大批披甲战象与精锐伙伴骑队，将重骑与主力象群悉数压在己方左翼，企图一举碾碎托勒密右翼。托勒密一世侦知敌阵虚实，当即把己方精锐骑队同步调集至右翼针锋相对；","他更针对战象设计独门利器，命铁匠赶制铁链串联的尖刺钉排预先铺在敌象冲锋沙地之前，配以大批弓箭与标枪手严阵待命。开战后两翼骑兵激烈绞杀难分胜负，德米特里一世催动战象群猛扑而上；","不料领头巨象一脚踏上铁刺钉障，剧痛难忍顿时发狂失控，标枪手趁势攒射象夫，失控象群反过来冲乱本方队列，尽数被托勒密军捕获。见到战象覆没，德米特里一世麾下骑兵军心大骇，被托勒密一世与塞琉古率骑迂回侧翼一举击溃；","托勒密一世顺势攻占加沙，更拨给塞琉古一支精兵东返夺回巴比伦，彻底改写了近东霸权格局。"],"history":"公元前三一二年，第三次继业者战争期间，埃及统治者托勒密一世在流亡来投的塞琉古鼓动下，率大军穿越西奈沙漠进军叙利亚门户加沙，迎战安提柯一世留守的年轻王子德米特里一世。面对德米特里一世部署在左翼的战象群，托勒密一世首创铁刺钉障配合标枪射手重创战象，继而在右翼骑战中迂回击溃德米特里一世骑兵，大获全胜并资助塞琉古重返巴比伦复国。","sources":"西西里的狄奥多罗斯·历史丛书·第十九卷；普鲁塔克·德米特里传"},
    "wei_wuqi": {"strategic":["公元前三八九年，魏国经变法强兵称雄战国，西河郡守吴起连年西进夺占河西沃土，扼住秦国东出咽喉。适逢魏文侯卒、武侯新立，秦惠公以为有机可乘，倾发全国兵马东攻河西门户阴晋；西河告急，吴起主动请缨，统魏武卒赶赴阴晋迎敌。"],"tactical":["阴晋南依华山余脉，北控渭洛原野，秦惠公亲督秦师压境筑垒。西河士卒素感吴起恩信，纷纷披甲请战；吴起特设分等酒食飨士，将未曾立功者置于次席以激其耻，编为前锋锐卒配车骑出击。交锋之际，求功心切的魏卒奋死直捣秦阵中坚，冲垮仓促征集的秦军前锋；秦惠公大败西遁，魏国由此久据河西。"],"history":"公元前三八九年，秦惠公倾发大军东进，猛攻魏国河西门户阴晋。魏西河郡守吴起平日治军恩信兼备，奏请魏武侯抽调尚未立功受赏的士卒为突击骨干，配以战车骑兵鼓行迎击，在阴晋城外以少击众大破秦师，稳固了魏国对河西之地的长期控制。","sources":"吴子·励士；史记·孙子吴起列传"},
    "wu_fuchai": {"strategic":["公元前四九四年，吴越因槜李之战结下死仇，吴王夫差铭记杀父之痛，督舟师步卒日夜备战将南下伐越。越王勾践探知吴军将动，不听范蠡劝阻，决意先发制人率水师北入太湖；夫差闻讯倾发精锐楼船出迎，两军主力会战于太湖夫椒山。"],"tactical":["太湖烟波浩渺，夫椒山孤峙湖中，勾践率越国舟师抢占水域严阵待敌。夫差见越阵稳固，趁入夜北风大作分遣翼舟环绕越寨张火鸣鼓，彻夜诈攻惊扰，令越军疲于奔命。破晓时分，夫差亲擂战鼓，统大翼楼船顺风全线猛撞敌阵；越水师大溃，勾践退困会稽山请降，吴国一时称雄东南。"],"history":"公元前四九四年春，吴王夫差为报父仇日夜练兵将伐越，越王勾践不听范蠡劝阻抢先发水师北上迎战于太湖夫椒山。夫差乘夜风设火炬疑兵惊扰越军水寨，次日顺风全线猛攻大破越水师，追困勾践于会稽山，迫越称臣入质。","sources":"左传·哀公元年；国语·越语；史记·越王勾践世家"},
    "wu_fuchai@-473": {"strategic":["公元前四七三年，曾威震中原的吴王夫差已入穷途。因连年远征齐晋耗尽精壮，又在笠泽夜战中丧尽野战主力，北方昔日盟友皆坐视不救；越王勾践倾发水陆大军合围吴都姑苏，筑垒断道步步紧逼，夫差唯有收拢残存军民据守孤城，作最后一搏。"],"tactical":["姑苏城池水门相通、重垣环抱，夫差屡遣精锐出城突击，企图打通太湖粮道。勾践严令越军深沟高垒不与硬拼，于城外筑越城锁死水陆通道，久困消耗城内积储。重围经年，城中粮绝兵疲，越军终发起总攻破城；夫差突围退据姑苏山遣使乞和，勾践不许留国，夫差愧见伍子胥于九泉，掩面自刎，霸业成空。"],"history":"公元前四七五年至前四七三年，吴王夫差历经笠泽惨败后野战主力丧尽，退保都城姑苏。越王勾践筑城断水长围姑苏三年，吴军粮尽援绝，公元前四七三年冬城破，夫差退奔姑苏山乞和遭拒，掩面自刎而死，吴国灭亡。","sources":"左传·哀公二十二年；史记·吴太伯世家"},
    "wu_fuchai@-484": {"strategic":["公元前四八四年，吴王夫差自夫椒破越后志得意满，开凿邗沟一心北上争霸中原。适逢齐国侵凌鲁国，鲁侯遣使联吴抗齐；夫差拒纳伍子胥先除越患之苦谏，倾发吴国精锐北渡淮泗会合鲁师入齐，与齐国上卿国书统率的齐军主力对阵于艾陵。"],"tactical":["艾陵山谷开阔，控扼齐鲁要冲，国书自恃本土车广兵足列阵迎战，夫差则亲领精锐坐镇吴中军。初战齐上军死命猛扑，一度击退吴国右翼；夫差稳居中坚亲自擂鼓，督吴国剑士奋勇反冲，一举凿穿齐军中阵，配合左翼合围包抄。齐师全线崩溃，主帅国书力战阵亡；夫差虽威震北方，却令吴国精锐远耗于外。"],"history":"公元前四八四年五月，吴王夫差不顾伍子胥先防越国之谏，志在北上争霸，应鲁国之约经邗沟北伐齐国，与齐上卿国书决战于艾陵。夫差亲领中军，先挫后胜全歼齐中军，阵斩齐帅国书及高无丕等将，威震齐鲁，但亦远耗吴国国力。定值：敌将取齐军主帅国书。","sources":"左传·哀公十一年；史记·吴太伯世家"},
    "wu_sunwu": {"strategic":["公元前五〇六年，吴国经孙武练兵与疲楚之策国力日盛；宿敌楚国则因令尹子常贪贿扣留蔡唐二君，致汉东屏藩背楚联吴。吴王与孙武决意大举伐楚，避开江淮旧路，溯淮水舍舟登陆；吴军会合蔡唐向导穿越大别山险隘直插汉水，与赶来堵截的子常主力逼近柏举。"],"tactical":["柏举位于大别山西麓通往汉水与郢都的原野门户。子常不听同僚凭汉水固守并断吴船后路之策，贪功渡水求战，连挫后退屯柏举。交锋当日，吴军看准子常治军无恩、楚卒离心，以精锐猛冲楚国中军，孙武挥全军压上掩杀；楚阵崩溃，子常奔郑，吴军五战五捷攻入郢都，威震诸侯。"],"history":"公元前五〇六年冬，吴王阖闾以孙武为将、伍子胥辅之，联蔡唐两国自淮汭舍舟登陆，越大别山奇袭楚国。楚令尹子常违沈尹戌夹击之议，渡汉水迎战连败，退屯柏举。吴军乘楚卒怨怠率先突击，大破子常主力，五战五捷攻入楚都郢城。","sources":"左传·定公四年；史记·孙子吴起列传"},
    "wuzhou_limu": {"strategic":["公元前二三三年，赵国陷入长平战后极凶险的存亡关头；前一年南线赵军在平阳遭秦将桓齮重创、主将战死，今岁桓齮又率虎狼秦师东越太行深入赵境，直逼邯郸东北门户宜安与肥下。","满朝无人可当强敌之际，赵王迁急发快马赶赴代雁门边塞，将长年镇守北疆、威震草原的名将李牧召回京师，筑坛拜为大将军。李牧精选精悍边骑与邯郸守军合编成军，昼夜兼程北上宜安前线，凭非凡智勇扛起挽救赵国社稷的莫大重担。"],"tactical":["肥下地处宜安东南要冲，原野坦荡，利骑兵驰突包抄。面对连战连捷、气焰熏天的桓齮大军，李牧深知敌军远来利在速战，当即施展昔日在雁门磨砺出的蓄势待发之术，筑起坚固营垒收兵自保，每日在营中杀牛犒赏将士、习射骑马，却严禁出营接战。","赵军将士久受恩养而求战欲狂，秦帅桓齮则久候不耐、认定李牧怯懦无能，竟轻率分出主力离开宜安大营，东向扑击肥下邑落。李牧侦知秦军兵力分散、老营空虚，骤然露出雷霆锋芒，先遣一枝劲旅闪电突袭攻陷秦军宜安大营，截获全部粮草家口；","待桓齮魂飞魄散率主力掉头回救时，李牧已在肥下布开严整中军与两翼精骑，如铁翼合拢般从左右两侧狠狠夹击行军散乱的秦师。秦军腹背受创、溃不成军，桓齮仅带残骑仓皇逃离赵境；李牧一战扭转乾坤，受封武安君，成为晚期赵国屹立不倒的长城。"],"history":"公元前二三三年，赵国在平阳惨败后危如累卵，赵王迁急从雁门调回抗匈名将李牧拜大将军统率南北合军抗击越太行来攻的秦大将桓齮。李牧移置北边蓄锐蓄势故法，在宜安筑垒坚守挫耗秦军锐气，待桓齮骄躁分兵东攻肥下之际，先袭占秦军空虚大营，再以两翼包抄战术在肥下全歼回救秦军主力，桓齮败逃，李牧因功受封武安君。","sources":"史记·廉颇蔺相如列传；战国策·赵策四"},
    "wuzhou_limu@-232": {"strategic":["公元前二三二年，距肥下大捷刚满一载，秦王嬴政调动重兵卷土重来，改由老练统帅王翦等人分南北两路钳击赵国；南路秦军陈兵邺城威逼邯郸，北路秦军自太原东越井陉攻克狼孟，前锋直插重镇番吾，企图将赵国拦腰夹碎。","危急关头，武安君李牧与副将司马尚沉着权衡，看出南线漳水城防完固易于牵制，北路番吾一旦失守则邯郸腹背受敌必亡无疑，遂留偏师严守南境长城，亲统赵国精锐主力星夜北上赶赴番吾迎战王翦大军。"],"tactical":["番吾背靠太行山井陉东口，前临滹沱河冲积原野，扼守着山西高原下出河北平原的咽喉锁钥。秦军北路主力刚出山隘拔城夺寨，补给全赖身后狭窄山道转运，极盼在平原速胜定局。李牧率赵军赶抵番吾外围后，利用滹沱河与太行山麓沟谷相错的地利，以深沟高垒卡住秦军南下大道；","同时发挥赵国边骑机动之长，频频迂回袭扰秦军出山粮道与侧翼营寨，趁秦军调动牵扯之际集中精兵猛击。连番血战之下，北路秦军攻势严重受挫，粮草难继；王翦深知李牧用兵滴水不漏、无机可乘，只得下令北路退回井陉山内，南路邺城秦军闻北路败退亦随之撤还。","李牧二度挫败强秦灭赵攻势，虽使赵军元气消耗甚剧，却令秦廷彻底明白李牧在位一日便绝难凭武力强破赵国。"],"history":"公元前二三二年，秦王嬴政不甘前一年肥之战惨败，再发重兵分南北两路大举攻赵：南路进抵邺城威胁邯郸，北路出太原连拔狼孟与番吾。赵武安君李牧与司马尚审察全局，南设坚防阻遏邺城秦军，亲统赵军主力北上番吾迎击秦北路大军，依托太行东麓险要再度击败秦师，迫使南北两路秦军无功撤退，但赵军自身亦损耗沉重。定值：秦军主将估算取王翦。","sources":"史记·赵世家；史记·廉颇蔺相如列传；战国策"},
    "wuzhou_limu@-244": {"strategic":["公元前二四四年前后，北方大漠草原上的匈奴骑射部落日渐强盛，单于头曼麾下控弦游骑频频南下袭掠赵国代郡与雁门边塞，来如急风、去似闪电，令中原重步兵防不胜防。赵廷委派良将李牧常驻雁门关外总揽北疆军务；","李牧将边境市租赋税全部充作军费，每日宰牛设宴厚养将士、练习骑射，却立下铁律凡遇匈奴入寇必须立即退入烽燧坞堡自保，敢私自出战捕虏者立斩。赵王一度责李牧怯战换人接替，结果新将屡出屡败、边地无法耕牧，只得再请李牧复出并应允不加掣肘。","李牧重施旧法又历数载，将士人人摩拳擦掌恨不得立时浴血报效，单于头曼则彻底断定李牧胆小如鼠，一场精心编织的塞外巨网悄然张开。"],"tactical":["雁门塞外黄沙莽莽，山谷与草滩相连。见全军锐气蓄至顶点，李牧精选良马铁骑、坚固战车与善射强弩手编成严密突击军团，故意放出漫山遍野的畜群与牧人散在塞外草场，在匈奴先遣小股游骑来掠时假装败退，丢弃大批人畜引诱大鱼上钩。","匈奴单于头曼闻报大喜过望，以为赵边唾手可掠，果真倾发草原主力铁骑浩浩荡荡越塞深入。待匈奴大军全部钻入预设谷地旷野，李牧亲自升帐擂响战鼓，正面重车强弩稳如山岳强弩齐发，埋伏在两侧远翼的赵国胡服精骑如两道铁流迂回包抄，瞬间锁死匈奴退路。","从未料到李牧竟敢决战的匈奴骑群阵脚大乱，在赵军车步骑严密绞杀下死伤蔽野，单于头曼仅率少数随骑狼狈远遁大漠；李牧乘胜灭襜褴、破东胡、降林胡，使匈奴十余载不敢南窥赵国边城半步。"],"history":"战国后期约公元前二四四年，赵名将李牧长年驻守代与雁门防备匈奴，以市租犒赏士卒，严令见胡骑即入堡收保不得妄战，致匈奴与赵王皆疑其怯，换将岁余屡败后复请李牧出镇。李牧如旧蓄势数载激起全军求战死志，随即纵牛羊牧民诱匈奴单于倾部深入，张设精选战车骑兵与强弩左右大翼合围，一战大破匈奴主力，十余年匈奴不敢近赵边。定值：年份估算取前二四四年，敌将取匈奴单于头曼。","sources":"史记·廉颇蔺相如列传"},
    "xibolai_dawei": {"strategic":["约公元前一〇二五年，迦南沿海的非利士五城同盟凭冶铁优势向内陆扩张，纠集联军深入犹大边境，意图压服以色列诸支派。两军隔以拉谷相持，非利士猛士歌利亚连日搦战，以色列军无人敢应；奉父命赴营送粮的年轻牧人大卫见状，毅然请缨步向阵前。"],"tactical":["以拉谷两侧丘陵夹峙，谷底横亘干涸溪床，两军分据南北山坡，谁先仰攻便陷被动。披重甲的歌利亚下谷挑战，大卫卸去甲胄，仅携牧杖与机弦拣石入谷；趁歌利亚轻敌逼近尚未及身，大卫疾旋机弦发石击中其额，趋前拔刀斩首。非利士军魂飞魄散弃营西逃，以色列军乘势追杀大获全胜。"],"history":"约公元前一〇二五年，沿海非利士五城同盟进军犹大山地边缘，与以色列军在以拉谷隔谷对峙。非利士巨人勇士歌利亚连日出阵搦战，年轻牧人大卫请缨上阵，弃重甲不用，以机弦甩石击杀歌利亚，以色列军乘势掩杀大败非利士军。史料不足：此战仅见于希伯来圣经撒母耳记上，年份系后世推算。","sources":"撒母耳记上·第十七章"},
    "xibolai_dawei@-995": {"strategic":["约公元前九九五年，大卫合以色列南北诸支派为一国，夺取山地要冲耶路撒冷立为新都。沿海非利士五城唯恐昔日附庸壮大断其商路，由亚吉统领联军东上山地，抢占新都西南门户利乏音谷，企图隔断以色列南北。大卫收拢勇士整备，亲统大军出迎利乏音谷。"],"tactical":["利乏音谷地处耶路撒冷西南走廊，两侧山坡遍生桑林，亚吉率非利士军在谷中广布营阵封锁大道。大卫先率军自高处猛冲，正面击穿敌阵；待敌重整再进，大卫改借桑林掩护迂回敌后，乘山风吹动树梢掩盖声响，骤自侧背奇袭。亚吉大军首尾失顾溃败西逃，以色列联合王国基业自此稳固。"],"history":"约公元前九九五年，大卫统合以色列南北诸支派并定都耶路撒冷，沿海非利士五城深感威胁，两度出兵屯驻耶路撒冷西南的利乏音谷企图扼杀新王国。大卫先正面冲决敌阵，复在再战中绕至桑林背后奇袭大破非利士军。定值：年份依圣经年代推算取前九九五年，敌将估算取同期非利士迦特王亚吉。","sources":"撒母耳记下·第五章；历代志上·第十四章"},
    "xin_baiqi": {"strategic":["公元前二六〇年，围绕上党归属爆发的秦赵长平大战已陷入关乎两国国运的生死僵局。赵军老帅廉颇在初战失利后依山筑垒坚壁不出，意图拖垮远道运粮的秦师；然而赵国本土国力终究逊于强秦，连年对峙之下粮草先行告急。","秦相范雎看准赵孝成王急于速决的焦虑心理，重金派细作入邯郸散布流言，诡称秦人最惧年轻气盛的名将之子赵括挂帅，廉颇老怯即将投降。赵王不听蔺相如与括母泣血苦谏，果然临阵撤换廉颇、改拜赵括为将；","秦昭襄王闻讯大喜，当即密诏战无不胜的武安君白起星夜秘密奔赴长平大营接掌上将军虎符，严令全军上下敢泄露武安君在军中者立斩不赦。"],"tactical":["长平谷地狭长深邃，丹水两岸营垒犬牙交错。赵括到任后尽废廉颇防守旧规，撤换军吏，亲率赵军主力渡过丹水向秦垒发起全线猛攻。白起早已布下口袋毒计，命秦军前锋接战即佯装不支，沿着预设谷道节节败退，将骄狂贪功的赵括主力深深诱至秦军坚固主壁之下；","与此同时，白起暗遣奇兵绕出赵军背后抢占长平故关与绵延石长城，彻底切断赵括大营与后方辎重营垒的联系，另派轻骑往来巡弋绝断赵军粮道。赵括猛攻秦壁不下，回首惊觉退路已绝，只得就地筑垒苦等外援。白起下令秦国河内丁男尽发前线遮绝诸侯救兵，将赵军死死困在绝谷之中四十余日；","赵卒断粮自相残食，赵括分四队轮番拼死突围皆被射回，最终亲率锐士冲阵中箭身亡，残军尽数投降遭白起坑杀，山东六国自此再无独抗强秦之力。"],"history":"公元前二六〇年，秦赵两军在长平相持日久，秦左庶长王龁难破廉颇坚壁。秦相范雎遣人入赵行反间计，赵孝成王中计以纸上谈兵的赵括取代廉颇；秦昭襄王秘密拜武安君白起为上将军赴前线接掌帅印，严令走漏风声者斩。白起设奇兵佯败诱赵括倾军追至秦壁，随即断其粮道与退路分割合围四十余日，射杀突围的赵括，坑杀降卒，重创赵国国本。","sources":"史记·白起王翦列传；史记·赵世家；战国策"},
    "xin_baiqi@-278": {"strategic":["公元前二七八年，秦国在司马错夺取黔中、打通巴蜀顺江水道之后，决意给南方宿敌楚国致命一击。当时楚顷襄王耽于逸乐、奸佞当道，朝政腐败而防务空虚。","秦大良造白起并未循淮北常规战线缓慢蚕食，而是大胆采取中心开花之略，率领精悍秦师自汉中翻越武当南下直插楚国富庶腹地，过河即下令拆毁桥梁、焚烧船只以示有进无退，并就地夺取楚人积粮充实军资。","在引西山长谷之水灌破拱卫楚都的北门重镇鄢城、彻底荡平楚军外围屏障之后，白起整军南指江汉平原核心，将兵锋径直推到了楚顷襄王坐镇的累世故都郢都城下。"],"tactical":["郢都南临浩瀚大江、北倚沮漳水网，城郭宏阔，乃是楚国累世经营的王业根本。然而鄢城惨烈陷落的噩耗传抵都城，楚国精锐守军早已在北线消耗殆尽，城中上下人心惶惧，楚顷襄王与群臣束手无策，根本组织不起像样的城外决战。","白起统率背水死战、士气如虹的秦国虎贲神速抵近郢都外围，分兵截断江汉水面逃路与周边属邑援军，随即架设攻城云梯冲车对郢都城垣发起排山倒海的猛烈强攻。","丧失斗志的楚都防线在秦军雷霆攻势下迅速土崩瓦解，楚顷襄王眼见王城不保，只得携王室宗亲狼狈弃城，一路向东北逃往陈城迁都苟延。白起率秦师昂首攻入郢都，继而西向攻取夷陵焚毁楚国先王陵墓以摧毁楚人复国信念，将江汉膏腴之地划为秦国南郡；","白起凭此不世奇功受封武安君，强盛一时的楚国自此元气大伤。"],"history":"公元前二七九年至前二七八年，秦大良造白起率精兵孤军深入楚国汉水流域，自断后路舟桥激励死战，先破邓城，继而在楚别都鄢城引蛮河水筑长渠灌城攻克重镇。公元前二七八年春，白起休整补给后挥师南下直扑楚顷襄王驻跸的国都郢城，一举攻占郢都、烧夷夷陵楚王陵寝，楚顷襄王仓皇东逃陈城，白起置南郡并受封武安君，楚国自此一蹶不振。","sources":"史记·白起王翦列传；史记·楚世家；水经注·沔水"},
    "xin_baiqi@-293": {"strategic":["公元前二九三年，秦国在宣太后与穰侯魏冉执政下锐意东出函谷，争夺通往中原腹地的河洛咽喉。","面对秦军步步蚕食，唇齿相依的韩国与魏国结成联军，并拉拢周室助阵，共推魏国大将公孙喜统帅三方兵马，浩浩荡荡进驻洛阳以南的伊阙天险，企图凭借优势兵力与山川关隘将秦军死死锁在崤函以西。危急之际，善识将才的穰侯魏冉力排众议，破格保举尚任左更的青年将领白起执掌东征帅印；","白起率领人数远少于敌的秦国锐士出函谷关东进，直抵伊阙山前，迎来了自己统兵生涯震动天下的成名首战。"],"tactical":["伊阙东西两山隔伊水对峙如天然门阙，地势险窄易守难攻，公孙喜统领的魏军与韩军分别依山傍水连营据守。白起抵近观察数日，敏锐看穿联军虽众却同床异梦，韩国指望兵多的魏军打头阵顶住秦锋，公孙喜所部魏军也不肯替韩国白白流血，两军彼此观望推诿、号令不一。","白起当即定下避实击虚、各个击破之策，先在韩军当面张设旗帜布下少数疑兵，装作即将强攻韩营之态令韩将死守不动；自己则亲统秦军全部精锐主力悄然绕越山岭，突然出现在公孙喜魏军大营的侧后方发起雷霆猛扑。魏军毫无防备，且见韩军隔岸观火不来相救，军心瞬间崩塌；","秦军乘势掩杀，将魏军主力彻底歼灭于伊水之畔并活捉主帅公孙喜，失去倚仗的韩军见状吓得争相弃营溃逃，白起挥骑追亡逐北连拔五城，秦国东进中原的大门自此彻底敞开。"],"history":"公元前二九三年，秦穰侯魏冉举荐左更白起接任主帅东征韩魏，韩国、魏国联合东周以魏将公孙喜为联军主帅，扼守洛阳南郊伊水两岸的伊阙险隘抗秦，联军兵力倍于秦师。白起洞察韩魏各自保存实力、互推对方先战的破绽，以少量疑兵正面牵制韩军，自率主力迂回伊阙山后奇袭猛扑魏军，一举歼灭魏师、生擒公孙喜，韩军随之溃败，白起由此一战成名。","sources":"史记·白起王翦列传；战国策·西周策"},
    "yan_leyi": {"strategic":["公元前二八四年，东方强国齐国在齐湣王治下极盛而骄，独吞富庶宋国后南侵楚地、西逼三晋，更妄图并吞周室自尊天子，引得列国人人自危。北方弱燕曾遭齐军破都覆国之惨祸，燕昭王即位后卑身厚币、筑台招贤，忍辱负重二十八载以图雪耻；","自赵魏投燕的名将乐毅洞察天下大势，向燕昭王进献连横合纵之策，指出齐国地大人众不可独攻，唯有联合诸侯共讨方能一击必杀。燕昭王遂倾国托付，拜乐毅为上将军，亲自出使串联赵、魏、韩、秦诸国达成伐齐盟约；","乐毅并佩相印统率五国浩荡联军东进，与齐将触子统率的齐国主力会战于济水西岸。"],"tactical":["济水西岸平原辽阔，齐军主帅触子依水扎营，见乐毅所统五国联军旌旗蔽野、锐气正盛，本欲依托水势持久相持以待联军生变。然而骄狂急躁的齐湣王却派使者赶赴阵前严词斥骂触子怯战，甚至恶毒威胁若不即刻决战便掘毁其先人坟墓、诛灭其九族。","触子心寒齿冷，决意借敌手使齐王自食恶果，遂违背兵家常理驱使军心浮动的齐军出营列阵。乐毅看准齐军上下离心、阵脚虚浮，一声鼓响挥动燕军居中死战，秦与三晋精兵分自两翼雷霆合击；","鸣金刚起，触子便率先调转马头弃军远遁，副将达子虽拼死收拢残兵亦难挽败局，齐国积蓄数代的野战主力在济西一朝覆灭。乐毅大获全胜后从容分赏诸侯盟军遣归本国，独率燕师乘胜渡过济水直捣齐都临淄，半年之内横扫齐境诸城，报了燕国世代血仇。"],"history":"公元前二八四年，齐湣王灭宋后穷兵黩武、四邻结怨，燕昭王拜魏国来投的贤将乐毅为亚卿上将军，联络秦、韩、赵、魏五国合纵伐齐。齐湣王命触子率齐军主力西渡济水拒敌，暗以灭族威胁触子速战；乐毅统五国联军于济水西岸迎头痛击，触子离心弃战逃逸，齐军主力覆没，乐毅遣返盟军后独率燕师长驱攻破临淄，连下齐七十余城。","sources":"史记·乐毅列传；战国策·燕策；吕氏春秋·权勋"},
    "yashu_saergong": {"strategic":["公元前七一四年，亚美尼亚高原的乌拉尔图与亚述争锋日久，国王鲁萨一世倚仗山险屡诱扎格罗斯诸侯叛亚述，令北疆岁无宁日。亚述王萨尔贡深知不破强敌难安两河，遂亲统大军翻越险隘深入高原腹地，兵指图什帕方向；鲁萨一世亦集结高原劲旅据守山谷迎截。"],"tactical":["乌拉尔图高山深谷交错，鲁萨一世陈兵险峰山谷之间，欲趁亚述军翻山疲敝以逸待劳。不料萨尔贡不等全军整队，亲率近卫骑队与战车悍然突击，一举凿穿敌军中坚，鲁萨一世弃营逃遁。萨尔贡乘胜扫荡高原迫近图什帕一带，回师又奇袭攻陷圣城穆萨西尔；鲁萨一世闻讯自尽，乌拉尔图自此一蹶不振。"],"history":"公元前七一四年，亚述王萨尔贡发动在位第八次远征，翻越扎格罗斯山脉讨伐北方劲敌乌拉尔图国王鲁萨一世。萨尔贡在瓦乌什山突袭大败鲁萨一世主力，扫荡乌拉尔图腹地逼近都城图什帕一带，回师奇袭攻陷圣城穆萨西尔，掳掠神庙珍宝，鲁萨一世闻讯自尽。","sources":"萨尔贡二世致阿舒尔神书信；亚述王家铭文"},
    "yashu_saergong@-710": {"strategic":["公元前七一〇年，亚述王萨尔贡已荡平叙利亚与乌拉尔图，唯南方巴比伦尼亚仍由迦勒底首领米罗达巴拉旦倚仗埃兰外援割据称王。萨尔贡决意收复两河下游，避开巴比伦北关坚防，率主力沿底格里斯河东岸南插，先行切断埃兰援道，自东南反包抄直逼巴比伦。"],"tactical":["巴比伦城垣宏伟、河渠纵横，米罗达巴拉旦见埃兰东援被断顿陷孤立，城中祭司贵族亦苦其苛敛而离心。萨尔贡步步紧逼，分兵肃清城外迦勒底营垒，对都城形成合围。米罗达巴拉旦自知孤城难守，趁夜弃城南逃海泽；城中祭司大开城门迎萨尔贡入城加冕，南北两河重归亚述一统。"],"history":"公元前七一〇年，已平定西方与北方的亚述王萨尔贡举兵南征割据巴比伦十余年的迦勒底王米罗达巴拉旦。萨尔贡沿底格里斯河东岸南下切断埃兰援道，合围巴比伦城，米罗达巴拉旦趁夜弃城逃往海泽，萨尔贡受祭司市民迎奉入城兼领巴比伦王号。定值：敌将取迦勒底巴比伦王米罗达巴拉旦。","sources":"萨尔贡二世年代记；巴比伦编年史"},
    "yashu_saergong@-720": {"strategic":["公元前七二〇年，萨尔贡初登亚述王位，两河与东境动荡未平。叙利亚哈马特首领伊卢比迪趁机称王，串联大马士革、撒马利亚诸城拒贡叛乱，并暗通埃及求援。一旦叙利亚走廊失控，亚述西向商赋尽绝；萨尔贡稳住东线后即刻统常备军西进，直扑伊卢比迪屯兵的卡尔卡尔。"],"tactical":["卡尔卡尔扼守奥龙特斯河渡口与南北官道，伊卢比迪纠合诸城步骑战车依河岸列阵。萨尔贡看准叛军各怀异心，抵阵即以重装战车与长矛步阵正面强压中路，同时遣精锐骑队自侧翼迂回包抄河岸退路。拼凑的联军防线顷刻崩溃，萨尔贡乘胜攻克卡尔卡尔、生擒处死伊卢比迪，黎凡特复归震慑。"],"history":"公元前七二〇年，亚述王萨尔贡初立、东方埃兰发难之际，哈马特王伊卢比迪串联阿帕德、西米拉、大马士革及撒马利亚残余结成叙利亚反亚述同盟，陈兵奥龙特斯河畔卡尔卡尔。萨尔贡疾驰西征，野战击溃联军，攻克卡尔卡尔并擒杀伊卢比迪，稳固了亚述对黎凡特的统治。定值：敌将取盟主伊卢比迪。","sources":"萨尔贡二世王家年表铭文；杜尔舍鲁金碑铭"},
    "yipilusi_piluoshi": {"strategic":["公元前三世纪初，新兴的罗马共和国先后折服萨莫奈与伊特鲁里亚，兵锋直逼南意大利沿海富庶的大希腊诸城邦。重镇塔兰托无力独抗强邻，遂渡海延请素有亚历山大再世之誉的伊庇鲁斯国王皮洛士西渡助战。","怀揣建立西方希腊大帝国雄心的皮洛士欣然应允，借取马其顿战舰，率领精悍长矛步卒、色萨利骑队与披甲战象横渡风浪险恶的海峡进驻塔兰托。罗马元老院拒绝皮洛士居间调停，派遣执政官拉维利乌斯统率罗马军团南下卢卡尼亚，企图在意大利盟友投向希腊人之前先发制人；","皮洛士遂率主力西出，在赫拉克利亚城外的西里斯河岸布阵迎击。"],"tactical":["赫拉克利亚原野被西里斯河一分为二，皮洛士屯兵河南岸，仅派前哨扼守浅滩以待塔兰托盟军赶来。拉维利乌斯深知迟则生变，果断命罗马步阵正面强涉浅滩，同时暗遣骑队自上游偷渡包抄希腊前哨，迫使皮洛士仓促亲率伙伴骑队顶上前线掩护马其顿方阵结成战列。","激战中皮洛士因铠甲华丽成为众矢之的，坐骑被刺倒地，他急与亲信互换衣甲，不料替身旋即阵亡，希腊军一度误以为国王战死而阵脚动摇，皮洛士当即摘下头盔驰骋阵前高呼振奋全军。罗马三线军团短剑投枪与希腊长矛密林反复冲杀，两军七进七退难解难分。","决胜关头皮洛士放出一直隐蔽未动的巨型战象冲击侧翼；罗马战马初见驮着箭塔的庞然巨兽，惊恐失控反冲本阵，皮洛士趁势挥骑掩杀一举夺下罗马大营，虽获大捷，麾下精锐骨干亦死伤枕藉。"],"history":"公元前二八〇年七月，应南意大利希腊城邦塔兰托求援，伊庇鲁斯国王皮洛士携马其顿式长矛方阵与印度战象渡海登陆意大利，与罗马执政官拉维利乌斯在卢卡尼亚的赫拉克利亚城外西里斯河畔首次交锋。罗马军团渡河与希腊方阵七度拉锯难分高下，皮洛士最后投入罗马人从未见过的战象冲垮罗马骑兵与侧翼，惨胜夺营，但己方精锐折损亦重。定值：战场改定为赫拉克利亚。","sources":"普鲁塔克·皮洛士传；哈利卡纳苏斯的狄奥尼修斯·罗马古事记"},
    "yipilusi_piluoshi@-275": {"strategic":["公元前二七五年，转战西西里两载的皮洛士虽曾把迦太基人逼至海角一隅，却因军政严苛失尽西西里希腊诸城人心，归航途中舰队又在墨西拿海峡遭迦太基海军重创，元气大伤。重返意大利本土后，往昔盟友萨莫奈人已被罗马军团打得奄奄一息，急求皮洛士北上救援。","此时罗马共和国派出名将执政官登塔图斯与同僚分走两路夹击南下，登塔图斯先行进驻萨莫奈重镇贝内文图姆外围险峻高地扎营，静待友军会合。深知合兵之后更难取胜的皮洛士决意孤注一掷，分兵阻滞另一路罗马军，自率全部精锐与战象赶赴贝内文图姆，企图抢在罗马合流前击破登塔图斯。"],"tactical":["贝内文图姆群山环绕，登塔图斯将罗马军营筑于陡峭山坡之上，拒不下山野战。皮洛士求胜心切，挑选最精悍的步卒与战象趁黑夜举火钻入崇山密林，打算绕至高地后方于拂晓居高临下奇袭罗马大营；","不料山道崎岖难辨，火把中途燃尽，部队在深山中迷路折腾整夜，直到太阳高升才筋疲力尽地出现在罗马营旁山头。早有防备的登塔图斯立即挥动生力军迎头反扑，将喘息未定的夜袭部队击溃并缴获数头战象。受此鼓舞，登塔图斯干脆率罗马军团下到谷底平原与皮洛士本阵决战；","皮洛士虽一度凭长矛与战象把罗马一翼逼回营壕，摸透战象习性的罗马守兵却从壕垒上强弓齐射并投掷燃烧标枪；一头受伤哀嚎的幼象掉头寻母，引得整群母象惊惶失控反冲踏碎皮洛士本阵，皮洛士无力再战黯然撤回希腊，南意大利自此尽归罗马。"],"history":"公元前二七五年，自西西里无功折返南意大利的皮洛士兵疲财匮，趁罗马两位执政官分兵进军萨莫奈之际，率主力扑向驻扎贝内文图姆高地的执政官登塔图斯。皮洛士夜间派精兵与战象翻山企图黎明突袭罗马营后，因山林迷路至天亮暴露，疲师遭登塔图斯反击；平原主战场上罗马兵以火箭射伤幼象引发母象狂乱反冲本阵，皮洛士战败放弃意大利远征。","sources":"普鲁塔克·皮洛士传；狄奥·卡西乌斯·罗马史残篇"},
    "yipilusi_piluoshi@-279": {"strategic":["公元前二七九年，皮洛士虽在赫拉克利亚首战重创罗马并一度兵临罗马城郊，坚韧不屈的罗马元老院却严词回绝和议，迅速补齐损毁军团，派遣执政官德西乌斯与同僚统领规模更为浩大的兵马南下阿普利亚拦截。","为克制前番令罗马吃尽苦头的印度战象，德西乌斯在军中特制了大批装有铁叉长杆、涂油火把与钩镰的重型抗象牛车，信心十足地在阿斯库路姆河岸布防。皮洛士率领伊庇鲁斯本部精锐与萨莫奈、塔兰托等意大利盟军北上迎击，两支强军隔着湍急河谷再度展开硬碰硬的血腥较量。"],"tactical":["阿斯库路姆外围首日战场河岸陡峭、林木丛生，战马与巨象根本无从涉渡驰骋，两军步卒在泥泞坡地上苦斗至天黑未分胜负。皮洛士连夜施计，天未亮便抢先派轻兵占领林坡险地，迫使德西乌斯不得不将罗马军团拉到开阔平缓的原野上列阵决战。","皮洛士将萨莫奈与意大利盟军编入马其顿长矛中队之间以增强弹性，正面顶住罗马重步兵不要命的劈砍冲击；当德西乌斯推出烈火熊熊的抗象战车迎堵战象时，皮洛士早有准备，命灵巧的投石手与标枪兵一拥而上射杀驾车牛夫、砍断挽具，轻易废掉了这批笨重火车。","紧接着皮洛士挥动战象群与王家骑队全力压向罗马侧翼，罗马大军支持不住败退回高地坚营；战后部下纷纷向皮洛士道贺大捷，望着满地阵亡的伊庇鲁斯亲信军官遗体，皮洛士黯然长叹若再赢罗马这样一场，自己便要只身归国了。"],"history":"公元前二七九年夏，伊庇鲁斯王皮洛士挥师进军阿普利亚，与罗马执政官德西乌斯及苏尔皮基乌斯统率的双执政官大军在阿斯库路姆苦战两日。首日在阿乌菲杜斯河林地山地交锋难施方阵与战象；次日皮洛士抢占平缓开阔地，以轻兵与标枪摧毁罗马特制的防象火盆牛车，投入战象突破罗马军团获胜，但麾下伊庇鲁斯精锐军官伤亡极重，留下再来一场这样胜利我便彻底完蛋的名言。","sources":"普鲁塔克·皮洛士传；哈利卡纳苏斯的狄奥尼修斯·罗马古事记"},
    "yue_goujian": {"strategic":["公元前四七三年，吴越世代宿怨迎来终局。越王勾践自会稽赦归后身自耕作、暗蓄兵威，趁吴王夫差北争中原屡耗其国，经笠泽大捷彻底打垮吴军主力。此时吴国羽翼尽折、外无诸侯来援，勾践决意灭吴雪耻，倾发水陆大军将夫差困守的姑苏团团包围。"],"tactical":["姑苏河渎纵横、城郭宏阔，夫差收拢残卒凭水陆重关死守。勾践知困兽犹斗不可急攻，在城外修筑坚垒，截断太湖与江淮通城水道，以长围消磨敌军元气。久困之下吴军突围皆被击回，城内粮尽援绝，勾践遂挥师总攻破城；夫差退上姑苏山乞求存祀，勾践纳范蠡之谏不许留国，夫差自刎，越国称霸东南。"],"history":"越王勾践夫椒兵败归国后十年生聚十年教训，先后趁夫差黄池争霸袭破吴都、于笠泽歼灭吴军主力，继而自公元前四七五年起围困吴都姑苏。经三年长围，公元前四七三年冬勾践攻克姑苏，拒夫差留国乞和，夫差自刎，吴国灭亡。","sources":"左传·哀公二十二年；国语·越语；史记·越王勾践世家"},
    "yue_goujian@-478": {"strategic":["公元前四七八年，越王勾践卧薪尝胆十余载后国富兵强，吴王夫差则因连年北征齐晋耗空精壮，国内又逢大旱饥荒。勾践见破吴时机已熟，尽起越国水陆劲旅北上讨吴；夫差闻警搜括余兵倾城南出，进驻笠泽北岸，欲凭江水天险阻挡越师。"],"tactical":["笠泽江面宽阔湍急，夫差沿北岸连营设防，与南岸越军隔水相峙。勾践避开白昼强渡，入夜分遣两翼偏师于上下游鸣鼓呐喊渡江，佯作包抄。夫差黑夜惊闻两侧鼓震，急分中军驰援两翼；勾践算定吴营中枢已虚，亲率精锐私卒衔枚潜渡中流，登岸突袭吴王本阵。吴中军溃散，两翼随之崩盘，吴国脊梁一战折断。"],"history":"公元前四七八年三月，越王勾践乘吴国连年北征耗竭及大旱饥荒之机大举伐吴，吴王夫差尽发国内余兵南下，隔笠泽设防。勾践入夜命左右两翼鸣鼓喧嚣诱吴军分兵，自率精锐私卒衔枚潜渡中流突袭夫差中军，三战皆捷歼灭吴国野战主力，奠定灭吴大局。","sources":"左传·哀公十七年；国语·吴语；史记·越王勾践世家"},
    "yue_goujian@-496": {"strategic":["公元前四九六年，吴国破楚后兵威冠于东南，与屡扰后方的越国积怨日深。适逢越国老王病逝、勾践初立，吴王阖闾趁越居国丧，亲统久战劲旅南下伐越，欲一举兼并越地。勾践临危不惧，急调越国锐士北上迎敌，两军主力对峙于吴越边境的槜李。"],"tactical":["槜李水网交错、田畴平衍，阖闾所统吴军结成严整方阵，勾践数次派兵冲锋皆被挡回。见强攻难撼，勾践遣死罪士卒分列走到吴阵前齐呼挥剑自刎；吴军上下惊愕张望，阵线瞬间松动。勾践看准破绽擂鼓挥全军猛冲，击溃吴师并重创阖闾足趾；阖闾伤重卒于归途，吴越死仇自此彻结。"],"history":"公元前四九六年夏，越王允常卒，勾践初立，吴王阖闾乘越丧亲率精兵南下伐越，两军对阵于槜李。勾践见吴阵森严难撼，遣死罪士卒于阵前排剑自刭，趁吴军错愕观望之际全军突击大败吴师，阖闾伤足病卒于归途。定值：敌将取吴王阖闾。","sources":"左传·定公十四年；史记·越王勾践世家"},
    "zhao_lianpo": {"strategic":["公元前二五一年，赵国虽在邯郸解围后稍得喘息，国内青壮却因长平与邯郸连年恶战伤亡惨重，田野多由妇孺耕作。北方邻邦燕国原本派国相栗腹借为赵孝成王祝寿之名出使邯郸结好，不料栗腹归国后向燕王喜密奏，声称赵国精壮尽丧长平，遗孤尚未成年，正是乘人之危举兵吞赵的天赐良机。","名将乐毅之子乐间与大夫将渠力谏赵乃四战强邦、军民习兵断不可伐，燕王喜一意孤行，竟倾发全国兵马分南北两路南侵，由栗腹亲统主力南指鄗城、卿秦另率偏师攻代。赵孝成王闻盟友背信偷袭，愤怒拜宿望老帅廉颇挂印出征，北上鄗城迎头痛击来犯燕师。"],"tactical":["鄗城地处邯郸以北平原大道，乃屏蔽赵都北门的军事重镇。燕相栗腹率领燕军主力一路推进至宋子与鄗城一带，自恃兵力充沛且认定赵人无兵可用，沿途骄狂松懈、队列拉长。廉颇深谙兵贵神速与攻心之道，看准燕军将骄兵惰、师出无名，而赵国将士皆对背盟偷袭的燕人恨入骨髓；","他遂舍弃持久战法，将赵军精锐高度集中于鄗城一线，趁栗腹前锋立足未稳之际骤然发起雷霆猛攻。","饱经秦赵血战洗礼的赵国老卒骁勇绝伦，铁骑与重步协同直捣栗腹中军大旗，燕军从未见识过如此凶悍的冲杀，阵线顷刻土崩瓦解，主帅栗腹在乱军中被赵兵当场斩杀，北路燕将卿秦亦在代地被乐乘击破生擒。","廉颇乘胜挥师北追直抵燕都蓟城城下合围，迫使惊惧失措的燕王喜拜将渠为相、割地五城卑辞谢罪，赵国国威由此重振。"],"history":"公元前二五一年，燕王喜听信国相栗腹所言赵壮者尽死长平、孤幼未壮可伐，不顾乐间与将渠苦谏，命栗腹攻鄗、卿秦攻代大举伐赵。赵孝成王起用老将廉颇与乐乘御敌，廉颇集中主力迎击轻敌深入的栗腹大军于鄗城，一举击溃燕军并阵斩主帅栗腹，乐乘亦于代地破擒卿秦；廉颇乘胜追奔长围燕都蓟城，迫使燕国割五城求和。定值：战场改定为鄗城。","sources":"史记·廉颇蔺相如列传；史记·燕召公世家；战国策·燕策三"},
    "zhao_lianpo@-260": {"strategic":["公元前二六〇年前后，赵国受纳韩国上党郡引发秦国倾力来攻，秦大将王龁攻陷上党诸邑后挥师北压太行腹地长平。赵孝成王委派威震诸侯的三朝宿将廉颇挂帅西御强秦。廉颇统率赵军主力赶抵长平山地，面对单兵搏杀凶悍的王龁秦师，深知秦军远越山岭运粮艰难、唯求速战；","赵军背靠本土，只要稳住阵脚持久消耗便能令秦师进退失据，一场比拼统帅定力的漫长对决就此展开。"],"tactical":["长平崇山峻岭连绵，丹水横穿谷底，廉颇起初在丹水以西山地分设空仓岭等多道前哨营垒节节迟滞敌锋。王龁督秦军猛扑强攻，接连拔除西岸前哨并斩杀赵军都尉与裨将；","廉颇见野战硬拼正中秦人下怀，毫不恋战贪功，果断将赵军主力悉数撤至丹水东岸，依傍险峻山脊垒石筑起高墙深堑，构筑起一道固若金汤的丹水防线。","王龁率秦军涉水逼近营门连番叫骂挑衅，廉颇却稳坐中军大帐，严令诸将谁敢擅自出战立斩不饶，只凭险关强弩居高射退攻营之敌，死死将秦国主力钉在太行深山之中动弹不得。","相持经年之下秦军师老粮艰，眼看持重方略渐见成效，后方赵王却难忍粮耗重压，听信秦国反间谣言强令阵前换帅，以纸上谈兵的赵括接替廉颇；老帅含恨交印离营未久，赵括便弃垒出击中伏败亡，空留无穷遗恨。"],"history":"公元前二六二年赵受上党，秦遣左庶长王龁攻上党进逼长平，赵孝成王命宿将廉颇率军迎防。初战前哨交锋失利后，廉颇审时度势退守丹水东岸修筑绵延石长城坚壁不出，任王龁百般挑战始终稳守，拖住秦军主力两载有余；惜公元前二六〇年赵王中秦反间计，嫌廉颇怯战而以赵括代之，终致长平覆军之祸。","sources":"史记·廉颇蔺相如列传；史记·白起王翦列传"},
    "zhou_jifa": {"strategic":["约公元前一〇四六年，殷商渐入暮年，商王子受暴虐无道、贵族离心，商军主力又久陷东南夷战事。西方渭水周族日益强盛，诸侯多叛商归周。周武王姬发见时机成熟，遍告诸侯兴兵伐商；周师会合西南诸方国部族自孟津冒雨东渡黄河，昼夜兼程直扑朝歌南郊牧野。"],"tactical":["朝歌南郊牧野平坦开阔，极利战车驰骋列阵。子受不及召回远征主力，仓促武装战俘与罪隶出城迎战。姬发阵前誓师申严军纪，命战车与虎贲猛士率先冲阵；商军前阵士卒素恨子受暴政，交锋未久便纷纷倒戈反冲本阵。商师大溃，子受退登鹿台自焚，姬发入主中原，开启周代礼乐格局。"],"history":"约公元前一〇四六年，周武王姬发乘商王子受连年征伐东夷、王畿空虚怨叛之机，率周军东渡孟津，会合庸、蜀、羌、髳、微、卢、彭、濮诸方国联军决战于朝歌南郊牧野。商军临时武装的战俘与罪隶临阵倒戈，周军击溃商师，子受登鹿台自焚，商亡周兴。异说：克商之年另有前一〇二七年、前一〇四五年诸说。","sources":"尚书·牧誓；史记·周本纪；利簋铭文"},
};
